(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-megablocks-dropless"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-1\">一 · 从一次尾时延尖刺说起：被丢弃的 token 与被撑大的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-2\">二 · 块稀疏的构造：从 token 指派到块级 offset</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-3\">三 · 适用边界：块大小是硬约束，负载分布是软约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-4\">四 · 代价结构：吞吐收益被三类开销吃掉的部分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-5\">五 · 失败模式与移植性：换框架就要重写的那部分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-6\">六 · 块稀疏分组 GEMM 的失效边界：一次尾时延尖峰暴露的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-7\">七 · 路由产物如何被折叠成块稀疏结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-8\">八 · 块级 padding 的插入位置与浪费公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-9\">九 · All-to-All 按块发送与接收端拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-10\">十 · 分组 GEMM 的 M 截断与 tcgen05 tile 映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-11\">十一 · combine 散射与 padding 位的排除</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-12\">十二 · 块稀疏分组 GEMM 的边界：块大小、负载偏斜与 kernel 移植性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-13\">十三 · 有效 FLOPs 与浪费率的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-14\">十四 · 块内截断与 tcgen05 tile 的对齐推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-15\">十五 · 块级 offset 与索引生成的复杂度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-16\">十六 · All-to-All 按块发送的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-17\">十七 · combine 散射与 padding 不参与加权的实现约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-18\">十八 · 浪费率上界的推导与块大小的选择判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-19\">十九 · 块稀疏分组 GEMM 的边界：块尺寸、偏斜负载与 kernel 税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-20\">二十 · 请求形态：块稀疏只在“块内够满”时兑现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-21\">二十一 · 批大小：块数量、非零块比例与 kernel 启动税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-22\">二十二 · 并发与专家负载分布：偏斜是吞吐的隐形税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-23\">二十三 · 负载不对时的三种可观测退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-24\">二十四 · 配方落地：把负载特征映射到参数与开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-25\">二十五 · 负载配方：块稀疏 GEMM 的甜区与崩点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-26\">二十六 · 硬件档位：从 block 粒度反推 SM 与 TMEM 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-27\">二十七 · 并行拓扑：块级 All-to-All 与专家维切分的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-28\">二十八 · 量化方案：块内截断与微缩放的相互作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-29\">二十九 · KV 策略：块稀疏 GEMM 不改变 KV 分页，但改变预填批形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-30\">三十 · 调度参数：批大小、块数与尾时延的三点权衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-31\">三十一 · 移植性与验证：自定义 kernel 的部署成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-32\">三十二 · 块稀疏 GEMM 部署配方的边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-33\">三十三 · 显存账本：块稀疏结构本身要花多少显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-34\">三十四 · 带宽：All-to-All 按块发送改变了通信粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-35\">三十五 · 吞吐：分组 GEMM 逼近稠密的上限在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-36\">三十六 · 通信与计算的重叠窗口被块粒度压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-37\">三十七 · 功耗：无效乘加是白烧的 Tensor Core 时间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-38\">三十八 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-39\">三十九 · 块稀疏分组 GEMM 的规模崩溃点：块粒度、索引开销与偏斜负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-40\">四十 · 精度问题的三个来源与隔离手法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-41\">四十一 · OOM 的真实成因：块级元数据与拼接缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-42\">四十二 · 批抖动与路由不均的耦合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-43\">四十三 · 尾延迟尖刺的定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-44\">四十四 · 监控指标体系与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-45\">四十五 · 块大小作为一等配置项的运维约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-46\">四十六 · 块稀疏 GEMM 的五类失效面：从精度漂移到尾刺的工程诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-47\">四十七 · 三条路线的问题坐标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-48\">四十八 · 决策表：按约束筛选，而非按跑分排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-49\">四十九 · 块大小与批大小的耦合选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-50\">五十 · 与量化、并行、分离式部署的叠加条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-51\">五十一 · 失败模式驱动的回退判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-megablocks-dropless-sec-52\">五十二 · 块稀疏分组 GEMM 的选型边界：与容量因子、专家选择路由的对照</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:534px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 534.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">路由器产出 token→专家的稀疏指派，按 block（如 128 tok…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">统计每个块的非零 token 数，生成块级 offset 与块内 toke…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">All-to-All 按块发送，接收端把同专家块拼接为连续段，不足一个 b…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对每个非零块调用分组 GEMM，块内 M 维按实际 token 数截断，N…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">combine 阶段按块内索引散射回原 token 位置，padding …</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-megablocks-dropless-sec-1\">一 · 从一次尾时延尖刺说起：被丢弃的 token 与被撑大的形状</h3>\n<p>某在线推理集群在晚高峰出现一类难以复现的故障：平均吞吐正常，但 P99 尾时延每隔数十秒出现尖刺，同时下游质量评测的分数在尖刺窗口内轻微下滑。排查后定位到两件事同时发生。第一，MoE 层采用容量因子路由：路由器为每个专家设定固定容量，超出容量的 token 被直接丢弃，其残差路径不再经过专家计算。容量因子在高峰期被压得很紧，丢弃率上升，被丢弃的 token 恰好集中在少数几个热门专家上，于是这些 token 的表示与稠密模型出现系统性偏差——这就是质量下滑的来源。第二，为了保住形状，分组 GEMM 的 M 维按“最大专家负载”统一 padding，热门专家撑满，冷门专家大量补零，GEMM 的有效算力被浪费，单层耗时随批次内负载偏斜程度波动，形成尾时延尖刺。</p>\n<p>这个事故把两个约束同时摆到台面上：<strong>不丢 token</strong>要求形状必须容纳最坏负载，而<strong>高效 GEMM</strong>要求形状规整。容量因子路由用丢弃换取规整，专家选择路由（expert-choice）用“专家挑 token”换取负载均衡，但它破坏了自回归解码的因果性——第 t 步的 token 可能被未来的路由决策影响，在投机解码与分块预填场景下不可接受。无丢弃块稀疏分组 GEMM 要解决的正是这个夹缝问题：既不丢 token，也不要求全局统一 padding，而是把不规则负载映射成块稀疏结构，让 GEMM 只在非零块上执行。</p>\n<p>需要强调的是它<strong>不解决</strong>什么。它不改变路由算法本身的质量，路由器给出什么指派就执行什么指派；它不解决专家并行的 All-to-All 带宽瓶颈，只改变发送粒度；它不替代量化与 KV cache 策略，NVFP4/FP8 的微缩放是另一条正交路径；它也不适用于稠密模型——没有稀疏路由矩阵，就没有块稀疏可言。换言之，它是“路由已定、形状待整”这一层的工程方案。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-2\">二 · 块稀疏的构造：从 token 指派到块级 offset</h3>\n<p>机制的核心是把 token×专家 的稀疏路由矩阵按固定 block 切分。以 128 token × 1 专家为一个块，路由器产出的每条 token→专家 指派先按专家分组，再按 token 序号在组内每 128 个切一块。统计每个块的非零 token 数 $n_b$，生成两级索引：块级 offset 数组（第 b 个非零块在拼接缓冲区中的起始位置）与块内 token 索引（该块内实际参与计算的 token 在原批次中的位置）。这两级索引是后续 dispatch、GEMM、combine 三个阶段共享的契约。</p>\n<p>All-to-All 按块发送而非按 token 发送：发送端把同一块的 token 连续打包，接收端把来自不同发送端的同专家块拼接为连续段。不足一个 block 的尾块用零填充到 128，但填充位置在块内索引中不出现，因此不参与后续加权。GEMM 阶段对每个非零块调用分组 GEMM，M 维按实际 $n_b$ 截断，N/K 维走 tcgen05 的 MMA tile——这正是块稀疏能贴近稠密吞吐的原因：截断只发生在 M 维，MMA 指令的 tile 形状与稠密路径一致，Tensor Core 利用率不被破坏。</p>\n<p>代价可以用浪费率刻画：</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>其中 $n_b$ 为第 b 个非零块的实际 token 数。注意求和只遍历非零块，全零块根本不进入 GEMM，这是与“按最大专家负载统一 padding”的本质区别：后者的浪费随负载偏斜线性放大，前者的浪费被限制在每块不足 128 个 token 的尾部。工程实测口径下块级 padding 浪费通常低于 10%，分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上。有效算力可写成：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}}=\\sum_{b\\in\\text{blocks}}\\mathbb{1}[\\text{nnz}_b&gt;0]\\cdot 2\\,M_b\\,N\\,K$$</div>\n<p>指示函数把全零块直接排除，$M_b$ 取 $n_b$ 而非 block_size，因此浪费只体现在 $M_b$ 与 block_size 的差额上。</p>\n<p>一个具体例子：批次内有 8 个专家，某层共 1024 条 token 指派。负载分布为热门专家 400 条、次热 300 条、其余六个专家合计 324 条且分布零散。按 128 token/块切分，热门专家 4 块（最后一块 16 条，浪费 112），次热 3 块（最后一块 44 条，浪费 84），零散专家各自 1 块、块内 token 数在 20–80 之间，浪费合计约 500。总浪费约 700/1024，落在 10% 量级附近；而若按最大负载 400 统一 padding 到 8 个专家，浪费将超过 2000 条 token 的算力。这个对比就是该算法存在的理由。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-3\">三 · 适用边界：块大小是硬约束，负载分布是软约束</h3>\n<p>块大小不是可调参数，而是硬约束。block 取小（如 32 或 64），块内尾部浪费少，但非零块数量成倍增长，kernel launch 次数、块级 offset 生成、块内索引构造的开销随之上升，在小批次解码阶段这些开销会压过 GEMM 本身的收益。block 取大（如 256），非零块数下降、launch 开销摊薄，但小专家块内 padding 显著——一个只有 20 条 token 的专家占一个 256 的块，浪费 236，浪费率瞬间突破阈值。128 token × 1 专家是材料给出的锚点，它对应 tcgen05 MMA tile 在 M 维上的自然粒度，也是“浪费可控”与“开销可控”的折中点。</p>\n<p>适用边界由此划出三条线。其一，<strong>批次规模</strong>：批大小决定块数量与非零块比例。批次过小，非零块占比低、块内 token 稀疏，块稀疏的索引开销占比高，此时稠密小核或融合解码核更合适；批次足够大，非零块填满，块稀疏才进入收益区。其二，<strong>负载偏斜程度</strong>：专家负载高度偏斜时，非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，吞吐可能低于预期；偏斜温和时块稀疏几乎等价于稠密分组 GEMM。其三，<strong>专家数量与并行拓扑</strong>：专家越多、单专家块越碎，块级调度越复杂；材料未给出具体专家数上限，工程判断应以“单卡非零块数量与 kernel launch 预算”为准绳，而非照搬某个专家数。</p>\n<p>还有一个常被忽略的边界：<strong>因果性要求</strong>。块稀疏本身不破坏因果性，但它的 dispatch 是按块聚合的，块内 token 的先后顺序在拼接后被打乱，combine 阶段必须依赖块内索引精确散射回原位置。若在投机解码的验证阶段复用同一批次缓冲区而未重置索引，散射会错位——这是实现层面的正确性边界，不是算法边界，但足以让一个“能跑”的 kernel 在尾时延窗口里给出错误结果。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-4\">四 · 代价结构：吞吐收益被三类开销吃掉的部分</h3>\n<p>把代价拆开看，块稀疏分组 GEMM 的净收益等于“省下的 padding 算力”减去“新增的索引与调度开销”。省下的部分由浪费率直接决定：浪费从统一 padding 的数十个百分点降到 10% 以下，GEMM 时间近似按比例下降。新增开销有三类。第一类是<strong>索引构造</strong>：每层都要扫描路由指派、按专家分桶、按 128 切块、统计 $n_b$、写 offset 与块内索引，这是一次 O(token 数) 的轻量遍历，但在解码阶段 token 数少、层数多，累计开销不可忽略。第二类是<strong>kernel launch</strong>：每个非零块一次分组 GEMM 调用，非零块数量直接乘进 launch 预算；这正是 block 不能取小的原因。第三类是<strong>dispatch/combine 的搬运量</strong>：按块发送使 All-to-All 的消息粒度变粗，单条消息更大、消息数更少，通常有利于带宽利用率，但接收端拼接需要连续缓冲区，显存占用按“块数 × block_size × hidden”预留，批次峰值时这块缓冲区与分页 KV、专家权重共同争抢显存。</p>\n<p>用公式表达净收益的临界点：设统一 padding 方案的单层 GEMM 时间为 $T_{\\text{pad}}$，块稀疏方案为 $T_{\\text{blk}}=T_{\\text{pad}}\\cdot(1-\\text{waste})+T_{\\text{idx}}+T_{\\text{launch}}$。当 $\\text{waste}$ 从 30% 降到 8%，GEMM 主体省下约五分之一的时间；若 $T_{\\text{idx}}+T_{\\text{launch}}$ 超过这个节省，块稀疏就是负收益。这解释了为什么该算法在预填阶段收益明确、在极短解码步上需要与融合大核方案配合使用——融合大核把分组 GEMM 与激活、量化揉进一个 kernel，正是为了压掉 $T_{\\text{launch}}$。</p>\n<p>一个工程上的具体判断：当单层非零块数量在数十量级、block 为 128 时，launch 开销相对 GEMM 主体可忽略；当非零块数量上升到数百，且每块 $n_b$ 远小于 128，说明批次内负载过于零散，此时应回退到按专家分组的稠密路径或增大 block，而不是继续堆块稀疏 kernel。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-5\">五 · 失败模式与移植性：换框架就要重写的那部分</h3>\n<p>三类失败模式在部署中反复出现。第一类是<strong>块大小失当</strong>：block 过小，kernel launch 与索引开销压过收益，表现为“开了块稀疏反而更慢”；block 过大，小专家块内 padding 浪费显著，表现为“浪费率没降下来”。第二类是<strong>负载高度偏斜下的索引开销</strong>：非零块数量与块内截断频繁变化，offset 与索引生成从轻量遍历变成热点，吞吐低于预期，且尾时延随批次组成抖动。第三类是<strong>移植性</strong>：块稀疏 dispatch/combine 需要自定义 kernel，块级 offset 的语义、块内索引的编码方式、combine 的散射顺序都是实现约定，跨框架移植时无法直接复用，换框架后必须重写并重新验证正确性——这不是文档问题，是数值正确性问题，散射错位不会报错，只会让质量评测缓慢漂移。</p>\n<p>与之相关的稳定性技巧落在两处。其一，把块级 offset 与块内索引做成显式的、可校验的中间产物，在 dispatch 前与 combine 后各做一次一致性检查（块内索引的并集应等于该块实际 token 集合，且不含 padding 位置），把静默错误变成显式失败。其二，把 block 大小与 tcgen05 MMA tile 的 M 维绑定，而不是留作自由参数——一旦 block 与 tile 不整除，M 维截断会引入额外的边界处理，抵消块稀疏的吞吐优势。</p>\n<p>最后落在工程判断上：这个算法的适用性不取决于模型有多少专家，而取决于“单层非零块数量是否落在 launch 预算内、块内平均 $n_b$ 是否接近 block_size”。前者决定调度开销能否摊薄，后者决定浪费率能否守住 10% 这条线。两个条件同时满足时，块稀疏分组 GEMM 是既不丢 token 又能贴近稠密吞吐的唯一现实路径；任一条件不满足，就该把这一层交回给容量因子路由或融合大核，而不是让一个实现复杂度高、移植性差的 kernel 在尾时延窗口里制造下一个事故。</p>\n\n\n<h3 id=\"alg-megablocks-dropless-sec-6\">六 · 块稀疏分组 GEMM 的失效边界：一次尾时延尖峰暴露的约束</h3>\n<p>某线上 MoE 推理服务在扩容后出现尾时延尖峰：路由分布随请求内容漂移，少数专家承接了远超均值的 token 量。容量因子路由为保住固定形状的 GEMM，只能丢弃溢出 token，被丢的 token 在 combine 阶段没有输出，表现为回答中出现语义断裂；改走专家选择路由后，因果性被破坏，自回归解码的已生成前缀与后续 token 的专家指派不再一致，长上下文场景下困惑度明显抬升。这正是无丢弃块稀疏分组 GEMM 要解决的工程问题：把 token×专家的不规则稀疏指派映射到规则的高效 GEMM，用块级 padding 代替 token 丢弃来对齐形状。它不解决路由本身的质量问题——路由器给出的指派是否合理、专家是否训练充分，都不在算法作用域内；也不解决跨节点 All-to-All 的带宽瓶颈，块稀疏只改变发送粒度与接收端拼接方式，通信量仍由非零块数决定。</p>\n<p>代价首先体现在块大小这一硬约束上。设第 b 个非零块的实际 token 数为 n_b，块容量为 block_size，则块级 padding 浪费为</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>以 128 token × 1 专家的块为例，块内 M 维按实际 token 数截断、N/K 维走 tcgen05 的 MMA tile，padding 位置不参与 combine 加权，浪费通常低于 10%，远小于按最大专家负载统一 padding 的做法。但块越小，kernel launch 与块级 offset、块内索引生成的开销越压过收益；块越大，小专家块内的零填充越显著。专家负载高度偏斜时，非零块数量与块内截断长度频繁变化，索引生成开销上升，分组 GEMM 吞吐会跌到稠密 GEMM 的 80% 以下——这一档吞吐优势只在负载相对均匀、块结构稳定时成立。</p>\n<p>第二个边界是实现复杂度与移植性。该方案要求自定义块稀疏 dispatch/combine kernel：发送端按块聚合、接收端把同专家块拼成连续段、不足一块的补零，combine 再按块内索引散射回原 token 位置。换框架后这套 kernel 需重写并重新验证正确性，跨框架移植性差。因此它适合路由分布可观测、框架栈相对固定的在线服务；若请求形态剧烈波动、或团队无力维护自定义 kernel，容量因子路由加适度丢弃、或稠密 GEMM 加统一 padding 反而是更稳的工程选择。</p>\n<h3 id=\"alg-megablocks-dropless-sec-7\">七 · 路由产物如何被折叠成块稀疏结构</h3>\n<p>本部分只沿一条数据流走：从路由器吐出 token→专家的稀疏指派开始，到块稀疏结构成形、跨卡发送、分组 GEMM 执行、combine 散射回原位为止。每一步给出输入、输出与该步在 Blackwell 上的代价落点。块稀疏 GEMM 的适用边界已在上一节界定，此处不再重复，只讲机制内部的时间顺序。</p>\n<p>第一步发生在路由器之后、任何通信之前。输入是形状为 <em>token×专家</em> 的稀疏指派矩阵——每个 token 对每个专家有一个权重，绝大多数位置为零。输出不是稠密矩阵，而是一份按块聚合的紧凑结构：以 128 token × 1 专家为一个 block，把 token 维按 128 切段，逐段检查该段内有多少 token 指派到该专家。这一步的代价是索引生成，属于纯访存与整数运算：它要读一遍路由分数（规模为 token 数 × 专家数），写出的却是远小于原矩阵的块表。在 B200 上这类 kernel 的瓶颈是 L2 与 HBM 之间的往返带宽，而非算力；当专家负载高度偏斜时，非零块数量与块内 token 数在每个 batch 间剧烈变化，索引生成的耗时会随之抖动，这正是该机制最隐蔽的尾时延来源。</p>\n<p>第二步把上一步的块表变成两个数组：块级 offset 与块内 token 索引。offset 数组长度为非零块数加一，记录每个块在拼接后连续段中的起始位置；块内索引记录该块里每个有效 token 的原始行号。输入是块表，输出是两个一维整型数组。代价在于这两个数组的长度是动态的，必须由 GPU 侧规约得出而不能在 host 端预分配，因此需要一个 device-side 的 scan/prefix-sum 与一次全局同步。工程上这通常意味着一次额外的 kernel launch 与一次 grid 级同步，在 decode 阶段单步只有几十微秒的预算里，这类固定开销不可忽略；预填阶段 token 多、块多，同样的开销被摊薄，占比反而小。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-8\">八 · 块级 padding 的插入位置与浪费公式</h3>\n<p>第三步是补齐。接收端把同一专家的所有块拼接成连续段，段内每个块占据固定的 128 行，块内实际 token 数不足 128 时用零填充。输入是块内索引与块表，输出是行数被 pad 到 128 整数倍的拼接矩阵，以及一份记录每块实际 token 数的元数据。这里的关键判断是：padding 发生在块内而不是发生在专家级，因此一个小专家只会浪费它自己那几个块里不足 128 的部分，而不会像按最大专家负载统一对齐那样，把每个专家都撑到最热专家的规模。</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>其中 $n_b$ 为第 b 个非零块的实际 token 数，block_size 取 128。这个比值直接决定分组 GEMM 的有效算力占比：被零填充的行仍然要过 MMA，它们贡献 FLOPs 却不贡献结果。给定事实给出的量级是块级 padding 浪费通常低于 10%，而分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上——两者并不矛盾，因为吞吐损失还包含索引、dispatch 与块内 M 维截断带来的 tile 利用率下降。显存侧的代价同样实在：拼接矩阵按 pad 后的行数分配，padding 行占用的是实打实的 HBM 容量与后续 GEMM 的读带宽，在 KV cache 已经吃紧的部署里，这部分冗余缓冲需要按峰值非零块数预留，而不能按平均块数预留。</p>\n<p>一个具体例子：某专家在一个 batch 内收到 300 个 token，按 128 切段得到 3 个块，前两块各 128 行满载，第三块 44 行有效、84 行补零。该专家的浪费为 84/300 = 28%，但它只影响这一个专家的三个块；若同一 batch 里有十个专家各收到几十个 token，每个都只占一个块，则每个块的浪费都接近 128 减实际数，总体浪费仍被块数分母摊薄。这说明浪费的分母是全体非零块的有效 token 总数，而非单个专家的负载，块数越多、块越满，比值越好看。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-9\">九 · All-to-All 按块发送与接收端拼接</h3>\n<p>第四步是跨卡搬运。输入是 pad 后的块数据与块表，输出是各目标 rank 上按专家归并好的连续段。与按 token 逐条发送不同，这里发送的单位是块：一个块内 128 行的行号、权重与隐状态被打包成一条消息，块表随消息同行，接收端据此知道该块属于哪个专家、块内哪些行有效。代价落在 NVLink 5 的链路上：消息数量从 token 级降到块级，元数据开销按块数而非 token 数计，这对 all-to-all 的启动开销是实质性的削减；但单条消息更大，要求发送缓冲按块对齐，链路带宽利用率取决于块是否被填满。块内有效行少时，搬运的是大量零，带宽被浪费——这与第三步的 padding 浪费是同一笔账在通信域的复现。</p>\n<p>接收端的拼接是这一步的真正难点。同一专家可能来自多个源 rank 的多个块，接收端要把它们按块序拼成一段连续内存，使后续分组 GEMM 能以单一基址加块级 offset 寻址。这要求接收缓冲按“专家 × 峰值块数 × 128”预留，峰值块数由路由分布决定而非由平均负载决定。工程判断在这里很直接：如果专家并行度提高、单卡专家数减少，则单卡上每个专家的峰值块数上升，接收缓冲随之膨胀；反之则块数分散、缓冲压力下降但通信跳数上升。这是一个必须与并行拓扑一起定的参数，不能事后调。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-10\">十 · 分组 GEMM 的 M 截断与 tcgen05 tile 映射</h3>\n<p>第五步是计算。输入是拼接后的块矩阵、专家权重与块表，输出是各块的输出激活。对每个非零块调用一次分组 GEMM：M 维按该块实际 token 数截断，即只算 $n_b$ 行而非 128 行；N 维为中间维度，K 维为隐层维度，二者用 tcgen05 的 MMA tile 覆盖。截断 M 是省算力的关键——被跳过的行不进入 MMA 的 M 维循环，但它们仍占据缓冲地址，所以省的是算力与读带宽，不是显存。有效 FLOPs 可写成：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}}=\\sum_{b\\in\\text{blocks}}\\mathbb{1}[\\text{nnz}_b&gt;0]\\cdot 2\\,M_b\\,N\\,K,\\quad \\text{waste}=\\frac{\\sum_b(\\text{pad}_b)}{\\sum_b M_b}$$</div>\n<p>tcgen05 的约束在这里变成硬性设计输入：MMA tile 的 M 维有最小粒度，$n_b$ 截断到 tile 粒度以下时，硬件仍按最小 tile 发射，块内不足一个 tile 的部分等于二次浪费。因此 128 这个块大小不是随手取的，它要与 tcgen05 的 M tile 粒度对齐，使一个块恰好覆盖整数个 tile，避免块内再出现半 tile。代价方面，分组 GEMM 的吞吐接近稠密 GEMM 的 80% 以上，缺口来自块间 M 维不一致导致的 tile 利用率波动、每块的 launch 与 offset 寻址开销，以及 TMEM 中累加器在块切换时的清空与重载。块越小，块数越多，这些固定开销占比越高；块越大，小专家块内 padding 越显著——这就是块大小作为硬约束的两端。</p>\n<p>一个具体例子：某层隐层 K 为数千、中间维 N 为数千，一个满载块做一次 $128\\times N\\times K$ 的 MMA 链，其算力被完全利用；而同专家一个 44 行的块，M 维截断后仍要按最小 tile 发射，实际算力利用率降到三分之一上下，但因为它只是一个块，对整层吞吐的拖累有限。真正的风险是大量这种半满块同时出现——专家负载偏斜时正是如此。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-11\">十一 · combine 散射与 padding 位的排除</h3>\n<p>第六步是回写。输入是各块的输出激活与块内索引，输出是形状与原始 token 序列一致的输出张量。combine 按块内索引把每行结果散射回原 token 位置，并按路由权重加权；padding 位置不参与加权，因为它们对应的不是真实 token，若误加会污染归一化分母。代价在于这是一次以块内索引为地址的随机写：写带宽取决于索引的局部性，块内索引在原 token 序列上是连续的（同一块的 token 在路由后仍保持相对次序），因此写模式是分段连续的而非全随机，这对 HBM 写合并友好。但跨块之间地址跳跃，写请求的合并度低于顺序写，实际写带宽低于理论峰值。</p>\n<p>这一步与第三步形成对称：padding 在进入 GEMM 前插入，在 combine 时被排除，两次操作都以块表为依据，块表因此在整条流水线上被读三次（索引生成、dispatch、combine），它的一致性就是正确性的全部。任何一次块表与数据不同步——例如接收端拼接顺序与发送端块序不一致——都会让散射写到错误位置，且不会报错，只会让输出数值偏移。这是该机制在工程上最需要验证的地方，也是跨框架移植时必须重写的核心 kernel 之一：块稀疏 dispatch/combine 没有标准接口，换框架即需重写并重新验证正确性。稳定性上还要盯住专家负载偏斜：非零块数量与块内截断频繁变化时，块级 offset 与索引生成开销上升，分组 GEMM 的 tile 利用率下降，吞吐低于预期的 80% 档位，此时应优先调块大小与并行拓扑，而非调批大小。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-12\">十二 · 块稀疏分组 GEMM 的边界：块大小、负载偏斜与 kernel 移植性</h3>\n<p>这套机制的代价几乎全部集中在“块”这个离散化粒度上。块容量 <em>B</em>（材料给出的典型值是 128 token × 1 专家）一旦固定，浪费与开销就同时被它锁定：块内实际 token 数 <em>n<sub>b</sub></em> 越小，零填充占比越高，而块的数量 <em>⌈T/B⌉</em> 又决定了 dispatch/combine 的索引生成与 kernel launch 次数。浪费公式为 <div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}(\\text{block\\_size}-n_b)}{\\sum_{b} n_b}$$</div> 它随 <em>B</em> 增大而单调恶化，因为小专家（被少量 token 选中的专家）几乎必然产生整块级别的空转；反过来 <em>B</em> 减半，块数翻倍，块级 offset 表与块内 token 索引的构造、All-to-All 的消息条数、以及每个非零块一次分组 GEMM 调用的固定开销全部上升。工程判断是：<em>B</em> 应取 tcgen05 MMA tile 在 M 维上的自然对齐值，使“块内 M 维按实际 token 数截断、N/K 维走 MMA tile”这一步不需要额外的重排，否则截断本身会引入新的搬运。</p>\n<p>失效条件有三个明确的触发面。其一是负载高度偏斜：当路由把绝大多数 token 压向少数专家时，非零块数量与块内截断长度在每个 micro-batch 之间频繁变化，块级 offset 与索引必须在关键路径上重新生成，这部分是纯标量/整数工作，无法被 MMA 掩盖，尾时延随之抬升，实测吞吐会明显低于“接近稠密 GEMM 80% 以上”的乐观区间。其二是块大小与专家数不匹配：专家数越多、单专家平均 token 越少，块内 <em>n<sub>b</sub></em> 越接近 1，padding 浪费迅速突破 10% 的经验阈值，此时块稀疏的收益被填充吃掉，反而不如按最大专家负载统一 padding 的朴素分组 GEMM 来得可预测。其三是跨框架迁移：dispatch/combine 是自定义 kernel，块布局、索引编码、零填充语义都是隐式契约，换到另一个框架必须重写并重新做正确性验证，这条成本不体现在单次推理延迟里，却决定了方案能否进入生产。</p>\n<p>系统代价要按流动顺序拆开看，每一步的输入输出与瓶颈都不同。路由阶段输入 token 隐状态、输出稀疏指派，代价是路由 GEMM 本身，与块结构无关；块聚合阶段输入指派、输出块级 offset 与块内索引，代价是索引构造的整数吞吐与一次全局同步，块越小这一步越贵；All-to-All 阶段输入按块打包的 token、输出接收端按专家拼接的连续段，代价是 NVLink 上的字节量与消息数，块级打包让消息数正比于非零块数而非 token 数，这是它相对逐 token 发送的优势所在；分组 GEMM 阶段输入零填充后的块矩阵，输出专家输出，代价是 MMA 利用率，块内截断保住了 M 维的有效性但 N/K 维仍需按 tile 对齐；combine 阶段按块内索引散射回原位置，padding 位置不参与加权，代价是一次 scatter 写回与对应的显存带宽。整条链上真正不可压缩的是 All-to-All 字节数与 GEMM 的 FLOPs，可压缩的是索引开销——而后者恰好是块大小选择失当时最先失控的一项。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>主要代价</th><th>块大小敏感度</th></tr></thead><tbody><tr><td>块聚合</td><td>稀疏指派 → 块 offset/索引</td><td>整数吞吐、同步</td><td>块越小越贵</td></tr><tr><td>All-to-All</td><td>按块打包 token → 专家连续段</td><td>NVLink 字节与消息数</td><td>消息数 ∝ 非零块数</td></tr><tr><td>分组 GEMM</td><td>零填充块 → 专家输出</td><td>MMA 利用率、显存</td><td>块越大 padding 越多</td></tr><tr><td>combine</td><td>块内索引 → 原 token 位置</td><td>scatter 写回带宽</td><td>弱敏感</td></tr></tbody></table>\n<p>由此得到一个可操作的容量判断：块稀疏分组 GEMM 适合专家负载相对均衡、单专家 token 数显著大于块容量的场景，此时非零块比例高、块内截断少、padding 稳定在 10% 以内，分组 GEMM 吞吐能贴近稠密 GEMM 的八成以上；一旦平均每专家 token 数逼近块容量，块粒度就不再是“对齐工具”而变成“浪费来源”，应改用更细的块或退回按专家打包的连续布局。真正决定这套方案能否落地的不是公式里的浪费比，而是索引生成是否被移出关键路径、以及自定义 dispatch/combine 是否被固化进所用框架的图捕获流程。</p>\n<h3 id=\"alg-megablocks-dropless-sec-13\">十三 · 有效 FLOPs 与浪费率的逐项拆解</h3>\n<p>块稀疏分组 GEMM 的收益全部落在一个式子上：<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}}=\\sum_{b\\in\\text{blocks}}\\mathbb{1}[\\text{nnz}_b&gt;0]\\cdot 2\\,M_b\\,N\\,K,\\quad \\text{waste}=\\frac{\\sum_b(\\text{pad}_b)}{\\sum_b M_b}$$</div>第一项是块级指示函数，它把“这个块有没有 token”变成一次分支判定，而不是让 kernel 在稠密网格上跑一遍空转。第二项 2·M_b·N·K 是块内实际参与乘加的元素数，M_b 是该块被截断后的有效行数，N 与 K 分别是专家权重矩阵的输出维与输入维——注意这里 N、K 不随块变化，因为同一个专家共享一份权重，块只是把 token 维切开。第三项是浪费率：分子是每块填充的行数之和，分母是所有块实际 token 数之和。关键的一步推导在于把“按最大专家负载统一 padding”的浪费率写成 (max_e n_e − n_e)/max_e n_e 的形式，再对比块级形式：前者由最热专家决定，后者由每块内部的 n_b 与 block_size 之差决定。当专家负载偏斜时，最热专家与均值之差被放大，统一 padding 的分子线性膨胀；而块级 padding 的分子只与“每块差多少行”有关，且块数越多、每块越小，单块差值越小。这就是为什么块级浪费能压到 10% 以下，而统一 padding 在偏斜负载下会成倍上升。</p>\n<p>工程代价上，这个式子的每一维都对应一条硬件约束。M_b 截断意味着 tcgen05 的 MMA tile 在 M 维上不能整除时仍要走完整 tile，实际发射的指令数由 ceil(M_b/tile_M) 决定，所以 M_b 越接近 tile 边界，浪费越低；N、K 固定则意味着权重在 TMEM 里的驻留策略可以按专家预编排，块切换时不必重载权重。吞吐侧，非零块比例直接决定 kernel 的有效占用率：若一批请求只激活少量专家，非零块少，SM 利用率掉下来，此时分组 GEMM 的吞吐由块数而非 FLOPs 决定。显存侧，块级 offset 与块内索引是额外的元数据，规模与非零块数成正比，通常远小于 token 激活本身。带宽侧，All-to-All 按块发送而非按 token 发送，单次传输的粒度变大、描述符变少，NVLink 5 上的小消息开销被摊薄。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-14\">十四 · 块内截断与 tcgen05 tile 的对齐推导</h3>\n<p>把 M_b 截断落到指令层，需要一次对齐推导。设 MMA tile 的 M 维为 t_M（tcgen05 的指令形状由硬件给定），则块内实际发射的 tile 数为 ⌈M_b / t_M⌉，有效利用率是 M_b / (t_M·⌈M_b/t_M⌉)。要让这个比值接近 1，块容量 block_size 应当是 t_M 的整数倍，且块内 token 数尽量填满。反过来，若 block_size 不是 t_M 的倍数，最后一个 tile 永远半空，浪费率被钉死在 (t_M·⌈block_size/t_M⌉ − block_size)/block_size 这个下界上。这就是“block 大小是硬约束”的数学来源：它不是调参偏好，而是 tile 形状与块容量之间的整除关系。以 128 token × 1 专家为例，若 t_M 取 64，则每块恰好两个 tile，块内截断只在第二 tile 上发生；若 t_M 取 128，则每块一个 tile，M_b 小于 128 时整个 tile 半空，浪费直接体现在这一块上。</p>\n<p>伪代码落到可实现层面，块内 GEMM 的循环骨架是：对每个非零块 b，取 offset_b 与 cnt_b，令 M_b = cnt_b，循环 tile 索引 i 从 0 到 ⌈M_b/t_M⌉−1，计算本 tile 的有效行数 r = min(t_M, M_b − i·t_M)，调用 tcgen05 MMA 时把 M 维设为 r（或在硬件只接受固定形状时用谓词屏蔽多余行），累加器落在 TMEM，N/K 维按专家权重的 tile 走。这里的关键工程判断是：谓词屏蔽与形状截断二选一。前者不改指令形状、靠 mask 掉无效行，实现简单但空转的 MAC 仍然耗电；后者改指令形状、需要硬件支持可变 M，省电但 kernel 分支更多。Blackwell 上 tcgen05 的 MMA 形状约束决定了多数实现走谓词屏蔽，代价是块内最后一块 tile 的功耗浪费，收益是 kernel 逻辑统一、不引入形状特化的编译分支。</p>\n<p>代价核算：以每块 128 token、t_M=64 为例，若某块只有 40 个 token，则发射两个 tile、有效 40 行，该块浪费 88 行，浪费率 220%；但这样的块在整体中占比小，因为路由聚合后大多数块接近满。真正决定总浪费的是“小块的数量 × 每块差值”，所以块数（由批大小决定）与块容量共同决定浪费分布。尾时延上，块内截断让最慢的块由最热专家决定，而非由统一 padding 的最大负载决定，尾时延的方差被压缩。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-15\">十五 · 块级 offset 与索引生成的复杂度</h3>\n<p>块稀疏结构的元数据是两级索引：块级 offset 数组给出每个非零块在拼接后连续段中的起始位置，块内索引数组给出该块内每个有效 token 的原始位置。生成这两级索引的代价是一次前缀和加一次散射写。设非零块数为 B，块内 token 总数为 T，则前缀和的复杂度是 O(B)，散射写的复杂度是 O(T)，两者都在 token 维上线性，不构成瓶颈；真正的开销在“统计每块非零 token 数”这一步，它需要对路由结果做一次按块的归约，归约的粒度是 block_size，若路由矩阵以位图或计数形式给出，归约可向量化；若以稀疏坐标列表给出，则需要一次排序或哈希聚合，复杂度升到 O(T log T) 或 O(T) 带常数。这就是专家负载高度偏斜时吞吐低于预期的原因：非零块数量与块内截断频繁变化，索引生成的常数项被放大，前缀和的写带宽与散射写的随机访问模式共同推高延迟。</p>\n<p>工程上把这一步压下去的手段是让路由器直接产出块级计数，而不是先出 token 级指派再归约。路由器在打分阶段就按块聚合，输出每个块的 token 数与块内局部索引，dispatch kernel 只做前缀和与拼接，省掉一次全局归约。代价是路由器的实现被绑到块结构上，块容量变化时路由器要跟着改，跨框架移植性进一步变差——这正是“需自定义 dispatch/combine kernel”的具体所指。带宽侧，块级 offset 与索引常驻显存，规模是 B 个整数加 T 个整数，相比 KV cache 与专家权重可以忽略，但在小批量、多专家、块数密集的场景下，元数据的读带宽会与激活读带宽竞争。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-16\">十六 · All-to-All 按块发送的通信账</h3>\n<p>按块发送把通信粒度从 token 提升到块，单条消息的有效载荷是 block_size × hidden，描述符数量从 T 降到 B。在 NVLink 5 与 NCCL 的语义下，小消息的固定开销（握手、描述符解析、通道调度）按消息数计，所以消息数下降直接压低通信启动开销；但单条消息变大后，接收端的拼接与零填充要在本地完成，填充部分占用显存带宽却不产生有效计算。设接收端某专家收到的块数为 k_e，其中不满块的块数为 f_e，则填充量是 f_e·(block_size − n_b) 之和，这部分数据要写进连续段再被 GEMM 读一遍，等于一次额外的写加一次额外的读，带宽代价是 2×填充字节数。填充比例受块容量与负载分布控制，块越小填充越少但消息数越多，块越大填充越多但消息越少——这就是块大小在通信与计算之间的折中曲线。</p>\n<p>一个具体例子：某专家在一批请求中收到 300 个 token，块容量 128，则聚合为 3 个块（128+128+44），第三块填充 84 行；若块容量改为 64，则聚合为 5 个块（64×4+44），最后一块填充 20 行，填充量降到约四分之一，但消息数从 3 升到 5，NCCL 的启动开销上升。工程判断是：当 hidden 维较大、单块载荷本身够大时，消息数不是瓶颈，应选小块降填充；当 hidden 维小、单块载荷接近小消息阈值时，应选大块压消息数。材料给出的 128 token × 1 专家是这两条曲线的常见交点，不是唯一解。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-17\">十七 · combine 散射与 padding 不参与加权的实现约束</h3>\n<p>combine 阶段按块内索引把专家输出散射回原 token 位置，padding 位置不参与加权。这一步的实现约束在于：散射写必须是按 token 的随机写，写地址由块内索引给出，而权重（路由概率）按 token 存，padding 位置没有对应 token，因此权重数组的长度等于有效 token 总数而非块容量×块数。若实现时误把权重按块容量展开，padding 位置会读到越界或零权重，前者是正确性错误，后者是静默的数值偏差。正确做法是在 combine kernel 里以 cnt_b 为循环上界，只遍历有效行，散射写的目标地址从块内索引取，源地址是 TMEM 累加器经 epilogue 写出的连续段。这样 padding 行既不读权重也不写回，浪费只停留在 GEMM 的空转上，不扩散到 combine。</p>\n<p>代价上，散射写的随机访问模式对显存带宽不友好，写合并率取决于块内索引的局部性：若同一块的 token 在原序列中连续，散射退化为顺序写；若路由打散了 token 顺序，散射的写事务数上升。工程上常把块内索引按目标地址排序后再写，用一次排序换写合并率，排序的代价是 O(cnt_b log cnt_b)，在小块上可忽略。尾时延上，combine 是整条流水线的最后一跳，它的延迟直接叠加到请求完成时间，所以散射写的合并率比 GEMM 的峰值吞吐更影响 SLO。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-18\">十八 · 浪费率上界的推导与块大小的选择判据</h3>\n<p>把浪费率写成可优化的形式：设块容量为 s，第 b 块的实际 token 数为 n_b，则 pad_b = s − n_b（仅对非零块计），浪费率 W = Σ(s − n_b) / Σ n_b = (B·s − T) / T = B·s/T − 1，其中 B 是非零块数、T 是有效 token 总数。这一步推导把浪费率从“逐块求和”化简为“块数与块容量的乘积除以总 token 数”，于是选择判据变得清晰：在 T 固定时，W 随 B·s 线性上升，而 B = ⌈T/s⌉ 在理想均匀分布下使 B·s ≈ T + s，故 W ≈ s/T。也就是说，块容量相对总 token 数的比值就是浪费率的下界，块越小这个下界越低。但块小到一定程度后，kernel launch 与索引开销的常数项压过收益，且每块的有效行数可能低于一个 tile，tile 利用率崩塌。所以块大小的选择是两条曲线的交点：一条是 W ≈ s/T 随 s 上升，一条是 launch 与索引开销随 B 上升即随 s 下降。材料给出的“block 越小浪费越少但 kernel launch 与索引开销越大，block 越大则小专家浪费显著”正是这两条曲线的定性描述，128 token 是常见交点而非理论最优。</p>\n<p>偏斜负载下这个推导要修正：B 不再等于 ⌈T/s⌉，而是由专家数与非零块分布决定，W = B·s/T − 1 中的 B 可能远大于 T/s，因为每个小专家至少占一个块。此时 W 的上界由“小专家数量 × s / T”主导，块越大、小专家越多，浪费越显著。工程判断是：专家负载越偏斜，越应该压小块容量，用消息数与 launch 开销换填充浪费；负载越均匀，越可以放大块容量，用填充换 kernel 效率。这条判据不依赖具体硬件型号，只依赖 T、专家数与负载分布三个量，可以直接写进容量规划的输入。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-19\">十九 · 块稀疏分组 GEMM 的边界：块尺寸、偏斜负载与 kernel 税</h3>\n<p>本方案的收益全部押在一个可调参数上：block_size。浪费公式 <span class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}(\\text{block\\_size}-n_b)}{\\sum_{b} n_b}$$</span> 的分子随 block_size 线性增长，而分母只由真实 token 数决定，因此块越大，每个非零块里“陪跑”的零填充越多。以 128 token × 1 专家为参照：某专家在某个 block 内只有 20 个 token，该块就产生 108 个空位；若专家负载长尾明显，这类小块会大量出现，waste 迅速逼近甚至突破 10% 的经验线。反过来把 block_size 压到很小，waste 下降，但非零块数量按 <span class=\"formula\">$$\\#\\text{blocks}\\propto \\frac{\\sum_b n_b}{\\text{block\\_size}}$$</span> 放大，块级 offset 生成、块内索引维护与逐块 GEMM 调用的固定开销开始压过算力收益——这是典型的 kernel launch 税，在尾时延上尤其明显。</p>\n<p>失效条件可以写成一条判据：当块级固定开销 <span class=\"formula\">$$T_{\\text{fixed}}\\cdot \\#\\text{blocks}$$</span> 超过因减少 padding 而省下的计算时间 <span class=\"formula\">$$T_{\\text{pad}}\\cdot(\\text{waste}_{\\text{large}}-\\text{waste}_{\\text{small}})$$</span> 时，缩小块就是负优化。工程上这意味着 block_size 必须与专家负载分布、批大小联合标定，而不是照搬 128 这个数字。偏斜负载是第二个失效面：非零块数量与块内截断长度频繁抖动，offset 与索引生成从“一次性预处理”退化为“每批重算”，分组 GEMM 的有效吞吐被拖到稠密 GEMM 的 80% 以下。第三个失效面是移植性：块稀疏 dispatch/combine 是自定义 kernel，换框架即需重写并重新验证正确性，索引错一位就是静默的 token 错位。</p>\n<table class=\"mini\"><thead><tr><th>参数取向</th><th>padding 浪费</th><th>块级固定开销</th><th>主要风险</th></tr></thead><tbody><tr><td>block 偏小</td><td>低</td><td>高，块数放大</td><td>launch 与索引税压过收益，尾时延变差</td></tr><tr><td>block 偏大</td><td>高，小专家块空位多</td><td>低</td><td>waste 突破 10%，算力被零填充吃掉</td></tr><tr><td>负载高度偏斜</td><td>随批波动</td><td>每批重算 offset</td><td>吞吐低于预期，索引生成成为瓶颈</td></tr></tbody></table>\n<p>系统代价要按三段拆：dispatch 段吃 NVLink 与 All-to-All 带宽，块级发送比 token 级发送少了元数据但多了块对齐的突发性；GEMM 段吃 tcgen05 的 MMA tile 利用率，M 维按实际 token 数截断意味着尾块永远填不满 MMA 的 M 粒度，这部分损失无法用 padding 换回；combine 段吃散射写回的索引带宽，padding 位置不参与加权是正确性要求，但也意味着这些位置在写回路径上被显式跳过，索引分支本身有代价。容量规划时应把 block_size 当作与批大小、专家数并列的一维搜索变量，用实测 waste 与块数共同定参，而不是先定块再调批。</p>\n<h3 id=\"alg-megablocks-dropless-sec-20\">二十 · 请求形态：块稀疏只在“块内够满”时兑现</h3>\n<p>块稀疏分组 GEMM 的收益来自一个前提：每个非零块里实际落进来的 token 数 $$n_b$$ 接近块容量 128。公式 $$\\text{waste}=\\frac{\\sum_{b}(\\text{block\\_size}-n_b)}{\\sum_{b} n_b}$$ 的分母是所有非零块的实到 token 总和，分子是这些块被零填充的空位总和。要让 waste 压在 10% 以下，平均块填充率必须高于约 91%。这不是路由算法能单方面保证的，它由请求形态决定：同一批请求里，token 到专家的指派越集中、越成团，块就越满；指派越散、越随机，块就越空。因此判断一份负载是否适合本算法，第一件事不是看专家数，而是看“单个专家在单个 batch 内能凑出多少个接近满员的 128-token 块”。</p>\n<p>适合的请求形态有三个可操作特征。其一是<b>长度分布偏长且方差可控</b>：长序列在分块预填阶段天然产生大量 token，单次前向的 token 总量足以把多数活跃专家喂到满块；短请求为主、长度集中在几十 token 的负载，token 总量少，活跃专家多而每专家分到的 token 少，块填充率被结构性压低。其二是<b>领域集中</b>：同一批请求若来自相近任务（同一类代码补全、同一类文档问答），路由分布会向少数专家聚拢，非零块数量下降而块内密度上升，waste 与索引开销同时受益；反之，混批多语言、多任务的开放域流量会把指派摊薄到大量专家上。其三是<b>批内语义同质</b>：连续批处理把不同请求拼进同一前向，若拼进来的请求主题离散，等于人为制造负载偏斜。</p>\n<p>反面形态同样清晰：高并发、超短请求、开放域混批。此时 token 总量虽大，但被切碎到极多专家上，每个专家的块内实到 token 数远低于 128，waste 上升，同时非零块数量暴涨，块级 offset 与块内索引的生成量随非零块数线性增长。工程判断可以落成一句可测的话：在目标流量上采样若干前向，统计“非零块的平均填充率”与“每千 token 的非零块数”，前者低于九成、后者偏高，就说明这份负载不该走块稀疏路线，应退回固定容量分组 GEMM 或换路由策略。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-21\">二十一 · 批大小：块数量、非零块比例与 kernel 启动税</h3>\n<p>批大小通过两条通道影响代价。第一条是块数量：批内 token 总量 $$T$$ 决定理论上限 $$\\lceil T/128\\rceil$$ 个块位，实际非零块数取决于路由分散度。批越大，单次前向覆盖的专家越多，非零块数增长，但每块的填充率未必同步上升——大批若来自离散请求，只是把稀疏摊得更宽。第二条是 kernel 启动与索引开销：每个非零块对应一次分组 GEMM 调用与一段索引构造，块数越多，固定开销占比越高。block 取 128 是这两条通道的折中点：再小则块数翻倍、启动税压过 padding 收益；再大则小专家块内空位显著，waste 公式的分子被少数冷门专家拉高。</p>\n<p>批大小的选择因此不是“越大越好”的单调问题，而是要找填充率与块数的乘积最优点。伪代码思路可写成一次离线扫描：对固定流量采样，令批大小 $$B$$ 在候选集上变化，对每个 $$B$$ 计算</p>\n<div class=\"formula\">$$\\text{cost}(B)=\\underbrace{c_{\\text{launch}}\\cdot N_{\\text{nz}}(B)}_{\\text{启动与索引}}+\\underbrace{c_{\\text{mma}}\\cdot\\sum_{b}M_b}_{\\text{有效计算}}+\\underbrace{c_{\\text{mma}}\\cdot\\sum_{b}(\\text{block\\_size}-n_b)}_{\\text{填充浪费}}$$</div>\n<p>其中 $$N_{\\text{nz}}(B)$$ 是非零块数，$$M_b$$ 是块内截断后的实际 M 维。前两项随批增大而摊薄，第三项随批增大先降后升——批大到把冷门专家也激活成独立块时，这些块的填充率极低，浪费项反噬。这条曲线的拐点就是该流量的推荐批大小。材料未给出具体批大小与 SLO 数值，所以工程上只能以实测拐点定档，不能拍一个通用数字。</p>\n<p>代价侧要盯住的是尾时延而非均值。分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上，这是稳态数字；但块级 offset 与索引生成在非零块数突增时会拉长单次前向的关键路径，表现为 P99 抬升。连续批处理下，一个超短请求挤进大批，可能触发额外非零块而不贡献填充率，属于典型的“批大小对了、批内容错了”。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-22\">二十二 · 并发与专家负载分布：偏斜是吞吐的隐形税</h3>\n<p>并发量本身不直接进入 waste 公式，它通过负载分布的稳定性起作用。低并发时，路由结果随机性强，相邻两次前向的非零块集合差异大，块级 offset 无法复用，索引生成每次都要重算；高并发且流量同质时，路由分布趋于稳定，非零块集合在时间上相关，dispatch/combine 的元数据可以缓存复用，实际开销下降。这就是为什么同一份模型在压测高并发与线上一波一波到达时表现不同：不是算力变了，是块结构的时变程度变了。</p>\n<p>专家负载高度偏斜是本算法最需要警惕的失败模式。偏斜有两种：少数热门专家吃掉大部分 token，其余专家零星接收。前者让热门专家的块满员、浪费低，但非零块数量随长尾专家增多而膨胀；后者让长尾专家的块填充率极低，waste 分子被这些块拉高。更麻烦的是偏斜随 batch 内容漂移：一次前向里某专家满块，下一次可能只剩十几个 token，块内 M 维截断频繁变化，tcgen05 的 MMA tile 调度与块级 offset 生成都要跟着重排，吞吐低于预期。材料明确指出这一失败模式，工程上的对策不是改算法，而是在路由侧加约束——例如对专家容量做软上限、对指派做局部聚合，把分布压回块友好的形状。</p>\n<p>并发规划还应考虑 All-to-All 的块粒度。按块发送意味着通信消息数与非零块数同阶，而非与 token 数同阶。低并发、高偏斜时块数多而每块有效载荷小，All-to-All 的有效带宽利用率下降；高并发、同质时块大而少，通信效率回升。这与分离式专家并行里的 All-to-All 调度是同一根带宽账，只是这里的计量单位从 token 变成了块。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-23\">二十三 · 负载不对时的三种可观测退化</h3>\n<p>第一类退化是<b>填充浪费抬头</b>。当流量以短请求、开放域混批为主，块内实到 token 数系统性偏低，waste 从 10% 以下向上走。此时分组 GEMM 仍在跑，但每个块的有效 M 维远小于 128，MMA tile 的利用率被截断吃掉，吞吐向稠密 GEMM 的 80% 以下滑落。观测手段是直接统计每块 $$n_b$$ 的分布，看均值与低分位；低分位块占比升高就是信号。</p>\n<p>第二类退化是<b>索引与启动开销反超</b>。块数暴涨时，块级 offset 生成、块内 token 索引构造、combine 阶段的散射都按块数计费，这些是标量与小向量操作，难以被 MMA 流水掩盖。表现为 kernel 时间线上出现大量短小 launch，SM 占用率下降而总时延上升。此时即便 waste 数字尚可，端到端吞吐也已经输了——这正是 block 取 128 而非更小的原因：更小的块会把这条退化曲线整体左移。</p>\n<p>第三类退化是<b>跨框架移植性带来的隐性成本</b>。块稀疏 dispatch/combine 需自定义 kernel，换框架后要重写并重新验证正确性。负载不对时，团队往往先怀疑路由或批调度，实际瓶颈却在自定义 kernel 与当前框架的融合边界上——例如与量化 MoE 解码融合大核的衔接、与分页 KV 共存时的显存布局。这类退化不体现在 waste 公式里，却直接吃掉部署窗口。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-24\">二十四 · 配方落地：把负载特征映射到参数与开关</h3>\n<p>把上述判断整理成一张可执行的配方表，比记公式更有用。核心是三列：负载特征、块参数、预期代价。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>块参数与开关</th><th>主要代价位</th></tr></thead><tbody><tr><td>长序列预填为主、领域集中</td><td>block=128，批尽量大，索引元数据缓存复用</td><td>填充浪费低，启动税被摊薄，吞吐接近稠密 80% 以上</td></tr><tr><td>短请求、高并发、开放域</td><td>退回固定容量分组 GEMM 或加路由聚合约束</td><td>块填充率低，waste 抬头，MMA 利用率下滑</td></tr><tr><td>专家负载强偏斜</td><td>路由侧软上限 + 局部聚合，块内截断稳定化</td><td>非零块数膨胀，索引生成开销上升，P99 抬升</td></tr><tr><td>解码为主、批小</td><td>与解码融合大核协同，避免逐块 launch</td><td>块数少但每块极空，启动税占比高</td></tr></tbody></table>\n<p>这张表的用法是：先用采样前向测出“非零块平均填充率”和“每千 token 非零块数”，落在左上格就走块稀疏，落在其余格先调路由再决定是否换算法。解码为主的负载尤其要小心——单次前向 token 少，块稀疏的结构优势无从兑现，此时应让解码路径走融合大核，把块稀疏留给预填与大批前向。</p>\n<p>最后落在工程判断上：块稀疏分组 GEMM 不是普适加速器，它是一份对负载有明确要求的合约——请求要够长、领域要够集中、批要够大、专家分布要够稳，四条同时满足时，128 token × 1 专家的块结构与 tcgen05 的 MMA tile 才能咬合，waste 压在 10% 以下、吞吐站上稠密 GEMM 的 80%。任何一条不满足，先改路由与批调度，再谈换 kernel；把负载配方当成部署前的准入检查，而不是上线后的调优项。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-25\">二十五 · 负载配方：块稀疏 GEMM 的甜区与崩点</h3>\n<p>这套方案的经济性完全由「非零块的比例」与「块内填充率」两个量决定。设批内 token 数为 $T$、专家数为 $E$、块容量为 $B$（如 128 token × 1 专家），则块总数约为 $\\lceil T/B\\rceil\\cdot E$，非零块数取决于路由分布的稀疏度。浪费由下式给出：</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(B-n_b\\right)}{\\sum_{b} n_b},\\quad n_b\\ \\text{为第 } b \\text{ 个非零块的实际 token 数}$$</div>\n<p>只有当每个非零块的 $n_b$ 接近 $B$ 时，浪费才被压到 10% 以下；一旦大量块的 $n_b$ 只有个位数，padding 占比迅速抬升，块稀疏退化为「用更多 kernel launch 换更少有效 FLOPs」。因此适配的请求形态是：批内 token 量足够大（使每专家平均命中数达到块容量的量级）、长度分布相对均匀、专家负载偏斜温和。长尾长度分布与极小并发是它的天敌——前者让块内 token 数在请求间剧烈抖动，后者让非零块数太少、索引与 launch 开销摊不薄。</p>\n<p>负载不对时的失效是分层的。并发过低时，非零块数少而每块 $n_b$ 远小于 $B$，分组 GEMM 的有效吞吐跌到稠密 GEMM 的零头，同时 All-to-All 按块发送的固定开销占比上升，尾时延被 dispatch/combine 两个自定义 kernel 主导。专家负载高度偏斜时，热门专家的块被填满、冷门专家产生大量近乎空的块，块级 offset 与块内索引每步都要重算，索引生成从配角变成瓶颈。块大小选错则是硬伤：block 过小，kernel launch 与索引开销压过收益；block 过大，小专家块内 padding 显著，$\\text{waste}$ 直接超标。</p>\n<table class=\"mini\"><thead><tr><th>负载状态</th><th>非零块/块内填充</th><th>系统代价</th></tr></thead><tbody><tr><td>大批量、长度均匀、偏斜温和</td><td>块多且接近填满</td><td>吞吐接近稠密 GEMM 的 80% 以上，浪费 &lt;10%</td></tr><tr><td>小并发、长尾长度</td><td>块少、$n_b\\ll B$</td><td>launch 与索引开销主导，尾时延抬升</td></tr><tr><td>专家负载极端偏斜</td><td>冷块近乎空、热块满</td><td>offset/索引重算频繁，吞吐低于预期</td></tr></tbody></table>\n<p>工程判断上，应把块容量当作与批大小联动的调参量而非固定常量：按目标 SLO 反推「每专家平均命中 token 数 ≥ 块容量」的最小批，低于该批就走稠密路径或合并请求；同时监控 $\\text{waste}$ 与索引 kernel 耗时占比作为切换信号。跨框架移植时，自定义块稀疏 dispatch/combine kernel 必须重写并重新验证正确性，这条成本在负载配方阶段就该计入容量规划，而不是等吞吐不达标再回头补。</p>\n<h3 id=\"alg-megablocks-dropless-sec-26\">二十六 · 硬件档位：从 block 粒度反推 SM 与 TMEM 预算</h3>\n<p>块稀疏分组 GEMM 的部署起点不是“选哪张卡”，而是“block 多大”。block 一旦定为 128 token × 1 专家，单块的 M 维上限就是 128，N/K 维交给 tcgen05 的 MMA tile 去铺。这意味着硬件档位的选择标准变成：一次 MMA 指令能吞下多大的 tile，以及 TMEM 能同时驻留几个累加器。B200/B300 这一档的价值在于 tcgen05 的 MMA 吞吐与 TMEM 容量允许把多个非零块的累加器并行驻留，接收端拼接出的连续段可以连续喂给 MMA，不必每块都做一次累加器换入换出；GB200/GB300 NVL72 这一档的价值在于机柜内 NVLink 5 域足够大，All-to-All 按块发送时块级消息不会被迫跨域降级。</p>\n<p>判断档位是否够用的量化口径是块级占用率：设单 SM 上同时驻留的非零块数为 <span>B_sm</span>，每块累加器占 TMEM 的份额为 <span>t</span>，则要求 <span>B_sm · t ≤ 1</span>。若 block 取 128 而 N 维 tile 取得过大，<span>t</span> 上升，<span>B_sm</span> 被迫下降，非零块就得排队等累加器，块稀疏带来的并行度被吃掉。反过来，N/K tile 取小会让单块 MMA 效率下降，分组 GEMM 吞吐离稠密 GEMM 的 80% 以上这条线就越拉越远。工程判断是：先按目标吞吐定 N/K tile，再由 TMEM 反推 <span>B_sm</span>，最后检查这个 <span>B_sm</span> 能否覆盖典型负载下的非零块并发数——覆盖不了就说明档位或 block 需要改，而不是靠调 batch 硬撑。</p>\n<p>具体例子：一个 128 token × 1 专家的块，实际只来了 37 个 token，M 维按 37 截断，N/K 维仍走完整 MMA tile。若该专家的 N 维恰好是 tile 的整数倍，这次 MMA 的有效利用率就是 37/128 的 M 向浪费加上零 N/K 浪费；若 N 维不是整数倍，还会叠加尾部 tile 浪费。这就是为什么硬件档位必须和 N/K 的整除关系一起看：tcgen05 的 tile 形状是硬的，模型的 intermediate size 是软的，二者对齐程度直接决定 <span>waste</span> 的实际分布。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-27\">二十七 · 并行拓扑：块级 All-to-All 与专家维切分的耦合</h3>\n<p>块稀疏结构把 All-to-All 的通信单位从 token 改成了块。发送端按块打包，接收端把同专家的块拼成连续段，不足一个 block 的补零。这条路径对并行拓扑的约束是：专家并行度必须与块拼接的连续性兼容。若专家维切得太碎，同一专家的块会散落在多个 rank 上，接收端拼不出足够长的连续段，分组 GEMM 就被迫退化成大量小块调用，kernel launch 与索引开销压过收益。因此拓扑设计的第一条是让每个 rank 上的专家集合尽量“整块”——按专家分组切分，而不是按 token 哈希切分。</p>\n<p>第二条约束来自块级 offset 与块内索引的生成位置。这些元数据在发送端算一次、接收端复用最省，但跨 rank 时元数据必须随块走，否则接收端要重扫一遍路由结果。伪代码思路是：发送端对每个目标 rank 维护一个块队列，块头携带 <span>(expert_id, n_b, offset)</span>，接收端按 <span>expert_id</span> 归并队列、按 <span>offset</span> 顺序拼接，拼接后的段直接作为分组 GEMM 的 M 维输入。代价是元数据带宽：每块至少几个字节的头，块数越多头开销占比越高，这也是 block 不能取太小的另一个原因。</p>\n<p>第三条是 NVLink 5 域边界。NVL72 机柜内的 All-to-All 可以按块细粒度发送而不明显抬尾时延；跨机柜时块级消息的固定开销被放大，块越小越吃亏。工程判断：把专家并行限制在单机柜域内，跨域只做层间流水或请求级分发，块级 All-to-All 不出域。具体例子：72 路专家并行放在一个 NVL72 域内，每 rank 持有一组专家，块按目标 rank 入队，接收端按专家归并；一旦把专家切到两个机柜，同一专家的块被劈成两半，拼接段长度腰斩，分组 GEMM 的有效 M 维随之腰斩，吞吐掉到稠密 GEMM 的 80% 线以下。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-28\">二十八 · 量化方案：块内截断与微缩放的相互作用</h3>\n<p>块稀疏的 M 维截断对量化方案提出一个特殊要求：截断后的块内 token 数 <span>n_b</span> 是动态的，量化粒度不能假设 M 是固定值。NVFP4 权重激活微缩放量化在稠密 GEMM 里按固定 tile 铺 scale，到了块稀疏这里，scale 的铺设必须跟着实际 <span>n_b</span> 走，padding 位置要么不参与量化、要么量化为零且不进入加权。若把 padding 也按正常 token 量化，combine 阶段虽不参与加权，但 GEMM 仍会算这些位置，浪费的 FLOPs 就变成了实打实的算力开销。</p>\n<p>量化方案的选择因此和 block 大小绑在一起。block 取 128 时，块内 token 数从 1 到 128 都可能出现，激活的微缩放若按 16 或 32 元素一组，块内截断会切在组中间，需要处理尾组。工程做法是让块内索引生成阶段同时产出量化组的边界信息，把 <span>n_b</span> 向上取整到量化组整数倍再做 GEMM，多出的位置补零——这会把 <span>waste</span> 从 token 级抬到量化组级，公式变为 <span>waste = Σ(ceil(n_b/g)·g − n_b) / Σ n_b</span>，其中 <span>g</span> 是量化组大小。g 越大，块稀疏的节省越被量化对齐吃掉。</p>\n<p>代价落在显存带宽上：权重侧若用 NVFP4，专家权重的读取量按块稀疏只读非零块对应的 N/K 切片，权重带宽随非零块比例下降；但激活侧的 scale 元数据是随块走的，块数越多 scale 读取越碎。具体例子：一个 batch 里 60% 的专家块非零，权重读取降到 60%，但每块都要读自己的激活 scale，若 block 取 64 而非 128，块数翻倍，scale 读取次数翻倍，带宽收益被抵消一部分。这就是 block 大小与量化粒度必须联合调的原因。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-29\">二十九 · KV 策略：块稀疏 GEMM 不改变 KV 分页，但改变预填批形状</h3>\n<p>块稀疏分组 GEMM 作用在 MoE 的 FFN 段，KV cache 本身仍按分页管理，二者在显存上共存但互不重叠。真正受影响的是预填阶段的批形状：分块预填把长请求切成 chunk，每个 chunk 的路由结果独立聚合成块，块数与 chunk 大小成正比。chunk 越小，块越碎，非零块比例越接近专家负载的真实分布，padding 浪费越低，但 kernel launch 与索引开销越高；chunk 越大，块内 token 数越接近 block 容量，截断浪费下降，但块数减少导致并行度不足。</p>\n<p>KV 策略的工程判断是：预填 chunk 大小按 block 容量对齐，取 128 的整数倍，使每个 chunk 的路由结果能整块聚合，减少跨 chunk 的块拼接。解码阶段每步 token 少，块内 <span>n_b</span> 很小，块稀疏的 M 维截断收益明显，但块数多、单块 MMA 利用率低，此时应把多个解码步的 token 攒批后再聚合，用批调度换块填充率。这与连续批处理的参数直接耦合：批窗口越长，解码块越饱满，<span>waste</span> 越低，但尾时延上升。</p>\n<p>显存侧的代价是块级元数据与 KV 分页表共存：KV 分页按页管理，块稀疏的 offset/索引按块管理，两套元数据都在显存里，块数越多元数据占用越大。具体例子：一个长请求预填切成若干 128 token 的 chunk，每个 chunk 路由到若干专家，产生若干非零块，块头与块内索引写入显存供 combine 阶段散射使用；若 chunk 取 64，块数翻倍，元数据占用翻倍，而 KV 分页表不变——这部分增量显存必须计入容量规划，不能只算权重与 KV。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-30\">三十 · 调度参数：批大小、块数与尾时延的三点权衡</h3>\n<p>调度参数的核心是批大小如何决定块数量与非零块比例。批越大，路由结果越接近专家负载的期望分布，非零块比例上升、块内 <span>n_b</span> 上升，分组 GEMM 的有效 M 维上升，吞吐靠近稠密 GEMM 的 80% 线；但批越大，单批的块级 offset 生成与 All-to-All 排队越长，尾时延越差。SLO 关注的是分组 GEMM 吞吐与尾时延两条线，材料未给出具体批大小与 SLO 数值，因此配方只能给结构性判断：先定尾时延上限，再反推单批可容纳的块数上限，最后在该上限内取使非零块比例最高的批大小。</p>\n<p>可复现的配置思路按以下顺序落地：第一步定 block 为 128 token × 1 专家，检查模型 N/K 维与 tcgen05 tile 的整除关系，不整除则调整 tile 或接受尾部浪费；第二步按 TMEM 预算定单 SM 驻留块数 <span>B_sm</span>，验证典型负载下非零块并发数不超过 <span>B_sm</span>；第三步把专家并行限制在单 NVLink 5 域内，按专家分组切分而非按 token 哈希切分，保证接收端能拼出连续段；第四步量化方案按块内截断对齐量化组，<span>n_b</span> 向上取整到组整数倍，padding 不参与加权；第五步预填 chunk 取 128 整数倍，解码攒批后再聚合，批大小由尾时延上限反推。</p>\n<p>这套顺序的代价是可预期的：block 取 128 使 <span>waste</span> 通常低于 10%，但块内截断频繁变化时 offset 生成开销上升；专家并行限制在单域内使 All-to-All 尾时延可控，但域内专家数上限约束了模型规模；量化组对齐使数值正确性可控，但组越大块稀疏节省越少。具体例子：一个专家负载高度偏斜的批，少数专家块块内 <span>n_b</span> 接近 128，多数专家块 <span>n_b</span> 只有个位数，非零块数量多而块内截断剧烈，此时 offset 与索引生成成为瓶颈，吞吐低于预期——这正是失败模式里“专家负载高度偏斜”的现场表现，调度参数应在此场景下优先增大批大小以抬升小块填充率，而不是缩小 block。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-31\">三十一 · 移植性与验证：自定义 kernel 的部署成本</h3>\n<p>块稀疏 dispatch/combine 需要自定义 kernel，跨框架移植性差是这套方案最实的部署成本。换框架意味着 dispatch/combine 重写并重新验证正确性，验证重点是三处：块级 offset 与块内索引在跨 rank 拼接后是否仍指向原 token 位置；padding 位置是否确实不参与 combine 加权；块内截断后的量化组边界是否与 GEMM 的 M 维一致。这三处任何一处错位，输出不会报错，只会静默地错位加权，属于最难查的一类缺陷。</p>\n<p>部署配方的最后一条工程判断是：把 block 大小、量化组大小、预填 chunk 大小三个参数锁成一组常量，写进 kernel 模板而不是运行时配置。理由是三者互相约束——block 变了量化组对齐要变，chunk 变了块拼接策略要变——运行时放开会让组合爆炸且难以验证。代价是灵活性下降，换模型若 N/K 维与 tile 不整除，需要重新实例化模板并重跑正确性验证，这部分工时必须计入上线计划。具体例子：从一种 intermediate size 换到另一种，tile 整除关系变化，尾部 tile 浪费分布变化，<span>waste</span> 公式里的 padding 项随之变化，若不重验就上线，吞吐与质量两条线都可能偏离预期。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-32\">三十二 · 块稀疏 GEMM 部署配方的边界与失效条件</h3>\n<p>这套方案的部署配方没有固定档位可抄，材料未给出硬件型号、量化与 KV 策略的具体取值，因此可复现的配置思路只能围绕一个硬约束展开：block 大小必须与 tcgen05 MMA tile 的 M 维对齐，同时让块内 padding 浪费落在可接受区间。以 128 token × 1 专家为块容量时，块级浪费为 <div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>其中 $n_b$ 为第 b 个非零块的实际 token 数。配方上应把 block 大小当作编译期常量而非运行期调参项：一旦选定，dispatch/combine kernel 的索引布局、offset 生成与 All-to-All 打包格式全部随之固定，改 block 等于重写 kernel 并重新验证正确性。并行拓扑上，块稀疏结构要求同专家块在接收端拼接为连续段，因此 EP 组内 rank 数应与专家数成整数关系，TP 只切 N/K 维、不切块内 M 维，否则块内截断长度跨 rank 不一致，offset 无法复用。</p>\n<p>量化方案的选择受块内截断影响：M 维按实际 token 数截断后，若采用 per-block 缩放（如 NVFP4 的块级 scale），缩放因子的粒度必须与 GEMM 的 M tile 边界一致，否则截断后的尾块需要额外 scale 重排，抵消掉块稀疏省下的算力。KV 策略与本方案正交，但批大小直接决定块数量与非零块比例：批越大，每专家块越接近满块，padding 浪费越低而 All-to-All 消息越大；批越小，非零块比例下降、块内截断频繁，索引生成开销上升。调度参数应把连续批处理的 token 预算与 block 容量挂钩，使每个调度步产生的 token 数尽量是 block 容量的整数倍，减少尾块数量。</p>\n<p>失效条件有三类。其一，block 过小：kernel launch 与索引开销压过收益，分组 GEMM 吞吐跌离稠密 GEMM 的 80% 以上这条线。其二，block 过大：小专家块内 padding 显著，浪费突破 10% 的量级，等于用算力换形状。其三，专家负载高度偏斜：非零块数量与块内截断长度频繁变化，块级 offset 与索引生成从配角变成瓶颈，尾时延被索引 kernel 主导而非 MMA。系统代价上，这套配方用自定义 dispatch/combine kernel 换掉了 token 丢弃，代价是跨框架移植性差——换框架需重写并重新验证，工程判断应是把 block 大小与 EP 拓扑写进部署契约，而不是留给运行期自适应。</p>\n<h3 id=\"alg-megablocks-dropless-sec-33\">三十三 · 显存账本：块稀疏结构本身要花多少显存</h3>\n<p>块稀疏分组 GEMM 的显存代价分三层：激活与权重、块元数据、以及 padding 占位。权重与激活按量化格式（NVFP4/FP8）存放，这部分与稠密 GEMM 同构，不因稀疏而缩小——块稀疏只省计算，不省权重驻留。真正新增的是块元数据：每个非零块需要块级 offset、块内 token 索引、以及接收端拼接后的连续段描述符。以 128 token × 1 专家为块粒度，块内索引是 128 个整型槽位，按非零块数量线性增长。当批内非零块比例接近 1（专家负载均匀、token 几乎填满每块），元数据规模与 token 数同阶，索引缓冲可达激活本身的数个百分点；当负载高度偏斜、大量块只有零星 token，非零块数逼近 token 数除以块内实际 token 数，元数据反而膨胀。第三层是 padding 占位：接收端把不足一块的专家段补零到 128，这部分显存被写入但不产出有效结果。</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>该式给出的是计算与占位的相对浪费，但换算到显存要乘上每 token 的激活字节数。块级 padding 浪费通常低于 10%，意味着为对齐付出的显存代价同样在个位数百分比；对比按最大专家负载统一 padding 的方案，后者在偏斜负载下浪费可达成倍，显存直接被尾专家撑爆。工程判断：块稀疏的显存优势不在省权重，而在把“形状对齐”的成本从最坏专家摊到每个块的实际占用上。KV cache 与专家权重的共存布局属于另一条目的主题，此处只需记住块元数据缓冲必须与 KV 分页池分开管理，否则碎片化会先于容量耗尽触发 OOM。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-34\">三十四 · 带宽：All-to-All 按块发送改变了通信粒度</h3>\n<p>块稀疏把 All-to-All 的发送单位从 token 改成块。发送端不再逐 token 打包，而是按块聚合：一个块对应一个专家、最多 128 个 token，块内 token 在源端已连续化，因此单次 RDMA/NVLink 传输的载荷更大、描述符更少。这在 NVLink 5 与 NCCL 路径上是实打实的收益——小消息开销被摊薄，接收端按块拼接同专家连续段时也少一层重排。代价出现在偏斜负载：非零块数量与块内截断频繁变化，块级 offset 与索引生成要在通信前完成，这段元数据计算落在关键路径上，与 All-to-All 的启动延迟叠加。</p>\n<p>带宽账要分两段看。发送段的有效载荷是实际 token 数乘以激活字节，padding 位置不参与加权，因此不占发送带宽——零填充发生在接收端拼接时，而非链路上。接收段的写入带宽则包含 padding：把不足一块的专家段补到 128，写放大比例正是上面的 waste 式。以块级浪费低于 10% 计，接收端写入带宽放大约一成，这在 NVLink 5 的高带宽下可接受，但在跨节点、带宽受限的拓扑上会成为可见项。另一个隐性带宽项是块内索引的散射：combine 阶段按块内索引把结果散回原 token 位置，索引本身要随激活一起搬运，属于纯开销流量。工程上应把索引压缩为块内偏移加位图，而不是每 token 一个绝对地址。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-35\">三十五 · 吞吐：分组 GEMM 逼近稠密的上限在哪里</h3>\n<p>吞吐的核心事实是分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上，前提是块稀疏结构能映射到 tcgen05 的 MMA 指令。映射方式决定上限：每个非零块调用一次分组 GEMM，块内 M 维按实际 token 数截断，N/K 维用 tcgen05 的 MMA tile。M 维截断意味着 MMA 的 M tile 未被填满时仍有指令级浪费，但 N/K 维满 tile 保证了 Tensor Core 的利用率主体。块大小 128 与 tcgen05 的 tile 形状配合得当，这是吞吐能到八成以上的结构原因。</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}}=\\sum_{b\\in\\text{blocks}}\\mathbb{1}[\\text{nnz}_b&gt;0]\\cdot 2\\,M_b\\,N\\,K$$</div>\n<p>有效 FLOPs 只计非零块，浪费体现在 M_b 小于块容量时的截断与 padding 上。吞吐崩点有三个。其一是块过小：kernel launch 与索引开销压过收益，非零块数量上升使每次 GEMM 的固定开销占比变大，SM 在 launch 间隙空转。其二是块过大：小专家块内 padding 显著，M_b 远小于块容量，Tensor Core 做大量无效乘加，有效吞吐掉到稠密的一半以下。其三是负载高度偏斜：非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，dispatch 与 combine 的元数据阶段吃掉本应给 GEMM 的时间。三者共同指向一个判断——块大小是硬约束，它不是可调超参，而是决定吞吐曲线的结构性选择。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-36\">三十六 · 通信与计算的重叠窗口被块粒度压缩</h3>\n<p>分离式专家并行下，All-to-All 与分组 GEMM 的重叠是吞吐的主要来源。块稀疏把重叠窗口切成块级片段：一个块的 GEMM 只能在其接收段拼接完成后启动，而拼接依赖该块全部 token 到达。块越小，单块 GEMM 越短，可重叠的粒度越细，但 launch 与索引开销越高；块越大，单块 GEMM 越长，重叠窗口越粗，尾块等待越明显。这就是块大小在通信侧的第二个约束：它同时决定计算 tile 形状与重叠粒度，两者方向相反。</p>\n<p>尾延迟在这里首次显形。一个批内所有块并非同时就绪，最慢到达的块决定该批 GEMM 的收尾时间。偏斜负载下，少数小专家块 token 稀疏、到达晚，却因块容量固定而占用与满块相同的调度槽位，形成“短块长占”的尾效应。工程对策是把块内 M 维截断做彻底——不足一块的段按实际 token 数发 GEMM，不让调度器按块容量预留资源；同时把块级 offset 生成提前到路由阶段，与 All-to-All 启动并行，缩短关键路径。材料未给出具体批大小与 SLO 数值，因此尾延迟的量化门限需按部署实测标定，不能套用固定阈值。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-37\">三十七 · 功耗：无效乘加是白烧的 Tensor Core 时间</h3>\n<p>功耗账与吞吐账同源。Tensor Core 在 M_b 截断与 padding 位置上的乘加不产出有效结果，却照常消耗开关能量。块级浪费低于 10% 时，这部分功耗占比与浪费比例同阶，属于可接受的白烧；块过大导致小专家 padding 显著时，无效乘加比例上升，功耗直接转化为散热与降频压力。B200/B300 的功耗预算在高负载批下本就紧张，无效乘加挤占的是有效吞吐的功耗额度。</p>\n<p>更隐蔽的一项功耗来自元数据阶段。块级 offset 与索引生成是标量密集的 kernel，跑在 SM 上但几乎不用 Tensor Core，属于低算术强度的功耗段。偏斜负载使这段开销上升时，整体能效比（有效 FLOPs 每焦耳）下降的速度快于吞吐下降的速度，因为元数据阶段吃功耗不产出。工程判断：把索引生成与 GEMM 放在不同 stream 上并限制其占用 SM 数，避免元数据阶段与 GEMM 争抢功耗预算，是块稀疏部署里容易被忽略的一步。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-38\">三十八 · 规模上去以后哪里先崩</h3>\n<p>按崩溃顺序排，块稀疏分组 GEMM 在规模扩张时最先撞墙的是自定义 kernel 的移植性与正确性验证，而非算力。块稀疏 dispatch/combine 需自研，跨框架移植性差，换框架后需重写并重新验证正确性——这是规模化的组织成本，不是单机性能问题。第二道墙是块大小失配：专家数增加、负载分布变宽后，固定 128 的块容量对小专家越来越浪费，对热点专家又不够切分，单一 block size 无法同时服务两端，吞吐曲线在专家数越过某点后掉头向下。第三道墙是尾延迟：非零块数量随批与专家数增长，块级 offset 与索引生成开销线性上升，dispatch 阶段逐渐成为批时延的主导项，SLO 在长批下先破。</p>\n<p>显存与带宽反而靠后。块级 padding 浪费低于 10% 的约束在专家负载可控时稳定，接收端写放大有限；All-to-All 按块发送摊薄了小消息开销，NVLink 5 下链路不是瓶颈。真正先崩的是调度与元数据的软件栈：块粒度越细，调度器要管理的块对象越多，块级 offset 与索引的生成、校验、散射三处都要在关键路径上完成，任何一处退化都会把分组 GEMM 从八成效吞吐拉回五成。规模上限因此由自定义 kernel 的实现复杂度与跨框架移植性决定，材料未给出具体专家数上限——这意味着上限不是算出来的，是在每次换框架、换拓扑时重新测出来的。工程上应把块大小、索引压缩格式、dispatch/combine 的 stream 划分做成可配置项，在专家数与批规模变化时重新标定，而不是沿用单点调优的结果。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-39\">三十九 · 块稀疏分组 GEMM 的规模崩溃点：块粒度、索引开销与偏斜负载</h3>\n<p>块稀疏分组 GEMM 的系统代价首先体现在块粒度这一硬约束上。块内 M 维按实际 token 数截断，N/K 维走 tcgen05 的 MMA tile，因此每个非零块的 GEMM 本身是高效的；真正的代价在块之外：块越小，padding 浪费越低，但非零块数量线性上升，块级 offset 生成、块内 token 索引构造、kernel launch 次数与 combine 阶段的散射寻址全部按块数计费。以 128 token × 1 专家为块容量时，一个批里非零块的数量大致等于被激活的（token 段，专家）组合数，索引张量本身就要占显存并产生额外的读写带宽。规模上去以后，先崩的往往不是 MMA 吞吐，而是这条索引通路：dispatch 前的块统计与排序、All-to-All 的块级元数据、接收端的块拼接，都是与 token 数近似线性、与块数成正比的轻量但高频操作，在小 block 配置下会把分组 GEMM 吞吐接近稠密 GEMM 80% 以上的优势吃掉。</p>\n<p>浪费与开销的权衡可以用块级 padding 公式直接量化：</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>其中 $$n_b$$ 为第 b 个非零块的实际 token 数。块级 padding 浪费通常 &lt;10%，远低于按最大专家负载统一 padding 的浪费；但这个 &lt;10% 是在负载相对均匀、块容量与专家负载匹配的前提下成立的。当专家负载高度偏斜——少数专家吸走大部分 token、长尾专家每块只有零星几个 token——非零块数量与块内截断频繁变化，小专家块内 padding 占比抬升，同时块级 offset 与索引生成开销随块数上升，吞吐低于预期。这是规模扩张时第二个崩溃点：偏斜不是靠调大 block 能解决的，调大 block 会让小专家浪费显著，调小 block 又让 launch 与索引开销压过收益，块大小落在一条窄的最优带上，而这条带随专家数、批大小与路由分布漂移。</p>\n<p>显存与带宽侧的代价同样按块计。接收端把同专家块拼接为连续段、不足一个 block 的用零填充，意味着每个专家的输入缓冲按块容量对齐分配，padding 位置虽不参与 combine 加权，但仍占用显存并参与 GEMM 的 M 维搬运；块级 offset、块内索引、块到专家的映射表在 dispatch 与 combine 两趟都要驻留或被反复读写。All-to-All 按块发送，通信量由块数与块容量共同决定，块级元数据在 NVLink 5 域内是可控的，但跨节点、跨 NVL72 机柜的专家并行下，块粒度越细，消息数量越多，通信启动开销与尾延迟越难压。尾延迟的来源是批内最后一个非零块：分组 GEMM 的完成时间由最慢的块决定，偏斜负载下某些块虽小却仍需一次完整的 tile 调度，SLO 关注的分组 GEMM 吞吐与尾时延在批大小增大时对块分布更敏感。</p>\n<p>功耗与工程判断落在同一处：块稀疏结构可映射到 tcgen05 的 MMA 指令，这是它能接近稠密 GEMM 吞吐的根基，但代价是实现复杂度高，需自定义块稀疏 dispatch/combine kernel，跨框架移植性差，换框架后需重写并重新验证正确性。规模上限因此不由硬件档位决定，而由这条自定义 kernel 路径的维护成本与块大小选择的鲁棒性决定；材料未给出具体专家数上限与批大小、SLO 数值，工程上应把块容量当作随负载分布在线调整的参数，并在偏斜检测触发时优先扩块而非丢 token，以守住无丢弃带来的质量对齐。</p>\n<h3 id=\"alg-megablocks-dropless-sec-40\">四十 · 精度问题的三个来源与隔离手法</h3>\n<p>块稀疏分组 GEMM 的数值问题很少来自矩阵乘本身，而来自“块内截断”与“padding 位置”的处理边界。第一类来源是块内 M 维截断：对每个非零块，kernel 只对实际 token 数 <span class=\"inline-math\">n_b</span> 做 MMA，剩余 <span class=\"inline-math\">block_size − n_b</span> 行用零填充。若填充区参与了 combine 阶段的加权散射，或归约时把零行计入了分母，就会出现“输出被稀释”的系统性偏差——表现为长尾 token 的 logits 幅值偏低。第二类来源是跨块拼接：接收端把同专家块拼成连续段时，块级 offset 若按填充后的容量而非实际 token 数累加，索引就会整体错位，症状是部分 token 的输出被替换成别的 token 的结果，且错误与路由分布相关、不可复现地随批变化。第三类来源是量化路径：块稀疏结构映射到 tcgen05 的 MMA tile 后，若 N/K 维 tile 与量化微缩放的分组边界不对齐，缩放因子会被错误地跨块复用。</p>\n<p>隔离手法是构造“单专家、单块”的最小用例：把路由强制为全部 token 指向同一专家，此时非零块数为 1、padding 比例可精确计算，用稠密 GEMM 的结果做逐元素比对，误差应落在量化噪声量级；再逐步放开到多专家、多块，观察误差是否随块数增长。工程代价上，这类比对必须在固定批形状下做，因为块级 offset 依赖批内路由分布，换批即换索引。一个具体例子：某层 8 专家、批内 512 token、block 为 128 token × 1 专家，若 3 个专家各只收到 40 个 token，则产生 3 个 padding 比例 68.75% 的块，这些块的输出必须与“只算 40 行”的结果一致，否则就是截断逻辑写错。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-41\">四十一 · OOM 的真实成因：块级元数据与拼接缓冲</h3>\n<p>块稀疏路径的显存超支通常不在权重或 KV cache，而在两块临时结构：块级 offset/索引表与接收端的拼接缓冲。索引表规模随非零块数线性增长，每个块需记录专家号、块内 token 数、块内 token 索引；拼接缓冲则按“每专家连续段长度 = 该专家所有块容量之和”分配，而非按实际 token 数分配。于是当专家负载偏斜时，小专家也会占满若干整块的容量，拼接缓冲的实际占用高于稠密分组 GEMM 的激活占用。</p>\n<div class=\"formula\">$$\\text{buf}_{\\text{combine}}=\\sum_{e}\\left\\lceil \\frac{n_e}{\\text{block\\_size}} \\right\\rceil \\cdot \\text{block\\_size} \\cdot d,\\quad \\text{overhead}=\\frac{\\text{buf}_{\\text{combine}}}{\\sum_e n_e \\cdot d}-1$$</div>\n<p>其中 <span class=\"inline-math\">n_e</span> 为专家 e 收到的 token 数，<span class=\"inline-math\">d</span> 为隐藏维。当每个专家平均不足一个块时，overhead 趋近于 <span class=\"inline-math\">block_size/n_e − 1</span>，可轻易超过 100%。诊断方法是把“非零块数 × block_size”与“实际 token 总数”两个计数在每层打印，二者之比即 padding 浪费的上界；若该比值随批增大而恶化，说明块大小相对专家粒度偏大。缓解手段是按专家维度切分拼接缓冲、按需增长而非预分配满容量，代价是引入动态分配与同步，增加解码步的启动延迟。一个具体例子：128 token × 1 专家的块在批内 64 token 时，每个非零专家块浪费一半容量，若专家数为 64，拼接缓冲的浪费量级与激活本身相当。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-42\">四十二 · 批抖动与路由不均的耦合诊断</h3>\n<p>批抖动指同一 SLO 下相邻批的端到端延迟方差过大，其根因在块稀疏路径上是“非零块数量随路由分布跳变”。块级 offset 与索引生成是串行前缀和，非零块数从 40 跳到 200 时，这段 CPU/GPU 侧的准备开销会阶跃上升；同时分组 GEMM 的 grid 维度随非零块数变化，SM 占用率在批间波动，尾延迟被拉长。路由不均则表现为少数专家占据大量 token，其块内截断接近满容量，而多数专家块内大量 padding，二者在同一 kernel 内混合，MMA tile 的有效利用率被拉低。</p>\n<p>监控上应采集三个量：非零块数 <span class=\"inline-math\">\\(B_{\\text{nz}}\\)</span>、块内 token 数分布的分位数（p50/p99）、以及 <span class=\"inline-math\">\\(B_{\\text{nz}}\\)</span> 的批间标准差。诊断判据是：若 p99 块内 token 数接近 block_size 而 p50 远低于它，说明负载偏斜严重，块大小需要下调；若 <span class=\"inline-math\">\\(B_{\\text{nz}}\\)</span> 标准差大而 p50/p99 接近，说明批内专家覆盖数在跳变，应考虑按专家亲和性做请求分组，把相似路由分布的请求放进同一批。代价是分组会牺牲批的到达灵活性，增加排队延迟，需在 SLO 的尾延迟预算内权衡。一个具体例子：同一批内 8 个专家的 token 数分别为 400、300、120、60、40、20、10、5，block 为 128 时前两个专家各占 4 块和 3 块接近满容量，后四个专家各占 1 块且 padding 比例超过 80%，该批的 padding 浪费主要由尾部专家贡献。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-43\">四十三 · 尾延迟尖刺的定位路径</h3>\n<p>尾延迟尖刺在块稀疏推理里有两类典型形态。其一是“块数尖刺”：某批因路由分散导致非零块数远超均值，dispatch 的 All-to-All 按块发送，块数翻倍即通信消息数翻倍，接收端拼接的同步点增多，单步延迟出现阶跃。其二是“索引重建尖刺”：块级 offset 依赖批内路由，每批都要重建，若实现中带主机侧同步或原子操作，重建耗时会随块数非线性上升。定位路径是先分离通信与计算：在 dispatch 前后各打一个时间戳，若尖刺落在 dispatch 段且与非零块数强相关，则是块数问题；若落在 GEMM 前的准备段，则是索引重建问题。</p>\n<p>系统代价上，尾延迟尖刺对 SLO 的伤害大于均值上升，因为连续批处理中一个长步会阻塞后续批的调度窗口。缓解手段包括对非零块数设上限并触发降级路径（把超出部分并入相邻块，接受更大 padding）、以及把索引生成移入独立的流水阶段与上一批的 GEMM 重叠。前者牺牲部分吞吐换确定性，后者增加流水深度与显存占用。一个具体例子：解码阶段批内 256 token、专家数 64、block 为 128 时，最坏情况每个专家一个块即 64 个非零块，而最好情况仅 2 个块，块数跨度 32 倍，dispatch 消息数与拼接同步点随之跨度 32 倍，这正是尖刺的来源。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-44\">四十四 · 监控指标体系与回滚判据</h3>\n<p>可观测性应围绕“块效率”建一条主指标链，而非只看端到端吞吐。核心指标是块级填充率 <span class=\"inline-math\">\\(\\rho = \\sum_b n_b / (\\sum_b \\text{block\\_size})\\)</span>，它与浪费公式互补；辅以非零块数、块内 token 分位数、dispatch 段耗时占比、以及分组 GEMM 相对稠密 GEMM 的吞吐比。回滚判据应写成可执行的阈值组合：当 <span class=\"inline-math\">\\(\\rho\\)</span> 低于设定下限且尾延迟 p99 超过预算，或分组 GEMM 吞吐比持续低于稠密路径的可接受比例时，切回容量因子路由或稠密分组 GEMM。注意回滚不是无损的——容量因子路由会丢弃 token，质量指标需同步观察。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要指标</th><th>判据方向</th><th>处置</th></tr></thead><tbody><tr><td>输出幅值偏低</td><td>块内截断后逐元素误差</td><td>随块数增长</td><td>检查 padding 是否参与归约</td></tr><tr><td>显存超支</td><td>拼接缓冲/激活比</td><td>随专家数上升</td><td>按专家切分缓冲、按需增长</td></tr><tr><td>批间延迟方差大</td><td>非零块数标准差</td><td>与 p99 延迟相关</td><td>请求按路由亲和分组</td></tr><tr><td>尾延迟阶跃</td><td>dispatch 消息数</td><td>与块数线性相关</td><td>块数上限 + 降级合并</td></tr></tbody></table>\n<p>回滚还需覆盖“换框架”这一失败模式：块稀疏 dispatch/combine 是自定义 kernel，跨框架移植后必须重新验证正确性，不能假定索引语义一致。工程判断是：把块稀疏路径作为可选后端挂在统一接口下，保留稠密分组 GEMM 作为对照实现，二者在同一批上跑一致性比对，比对失败即自动回滚，代价是双路径常驻带来的显存与编译产物开销。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-45\">四十五 · 块大小作为一等配置项的运维约束</h3>\n<p>块大小是硬约束而非可调超参，它同时决定 padding 浪费、kernel launch 与索引开销、以及小专家的浪费敏感度。运维上应把 block_size 与专家数、批形状绑定成配置矩阵，在容量规划阶段就固定，而不是运行期动态改。诊断“块大小失当”的方法是扫描两个极端：把 block 减半，观察 kernel launch 与索引开销是否压过浪费收益（表现为吞吐不升反降）；把 block 加倍，观察小专家块的 padding 比例是否显著上升（表现为 <span class=\"inline-math\">\\(\\rho\\)</span> 下降而 GEMM 有效利用率不变）。</p>\n<p>一个具体判断：当批内平均每专家 token 数明显低于 block_size 时，块稀疏路径的浪费主要由块容量而非路由丢弃造成，此时应下调 block 或改用更细的专家切分；反之当平均每专家 token 数远高于 block_size 时，块数增多带来的索引与 dispatch 开销成为主项，应上调 block 并接受尾部小专家的浪费。这一权衡没有解析最优解，只能靠在目标硬件与目标批形状上实测 <span class=\"inline-math\">\\(\\rho\\)</span> 与尾延迟两条曲线取交点。最后落在机制上：块级 offset 与块内索引的生成必须与 GEMM 的 grid 维度解耦，让块数变化只影响 grid 而不触发主机侧同步，这是把尾延迟尖刺压到可预测范围的结构性前提。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-46\">四十六 · 块稀疏 GEMM 的五类失效面：从精度漂移到尾刺的工程诊断</h3>\n<p>块稀疏分组 GEMM 的失效并不集中在“算得慢”，而是集中在“形状对不上”。第一类精度问题来自块内截断与 padding 语义的错位：块内 M 维按实际 token 数 <em>n<sub>b</sub></em> 截断，N/K 维走 tcgen05 MMA tile，若 combine 阶段把 padding 位置误纳入加权，或块级 offset 与块内索引在 All-to-All 前后不一致，就会表现为个别专家输出被零污染、路由权重归一化偏移。诊断抓手是逐块比对 <em>n<sub>b</sub></em> 与散射回写的 token 计数，并单独跑一条“全块 padding 置零、权重不参与”的对照路径；公式上盯住 <span class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}(\\text{block\\_size}-n_b)}{\\sum_b n_b}$$</span> 的实时分布，waste 突然抬升往往先于精度漂移出现，是索引错位的早期信号。</p>\n<p>第二类是 OOM 与批抖动。块稀疏结构把显存压力从“按最大专家负载统一 padding”转成“按非零块数 × block_size”分配，块数量随批大小线性增长，非零块比例又随路由偏斜波动；当专家负载高度偏斜时，非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，接收端拼接连续段的临时缓冲随之膨胀。监控应把“非零块数 / 总块数”“块内平均 <em>n<sub>b</sub></em>”“dispatch 缓冲峰值”三者并列，任一越界即触发批大小回退，而不是等 OOM 发生后再降批。</p>\n<p>第三类是路由不均与尾延迟尖刺。block 过小则 kernel launch 与索引开销压过收益，block 过大则小专家块内 padding 浪费显著，128 token × 1 专家的固定切分在长尾专家上会放大尾刺：少量 token 落入独立块，块内 <em>n<sub>b</sub></em> 远小于 block_size，GEMM 的有效 FLOPs 被 padding 稀释，单块延迟却不降。诊断用分块延迟直方图而非均值，把 P99 块延迟与块内 <em>n<sub>b</sub></em> 做散点，低 <em>n<sub>b</sub></em> 高延迟的块即为尾刺源；对策是块大小与专家负载分布联动调参，而非全局固定。</p>\n<p>第四类是移植性失效：需自定义块稀疏 dispatch/combine kernel，跨框架移植性差，换框架后需重写并重新验证正确性，回滚路径必须保留一条“容量因子路由 + token 丢弃”的旧链路作为对照基线，并以块级 offset 校验和作为灰度发布的门禁。监控指标建议落一张最小表：waste 分布、非零块比例、dispatch 缓冲峰值、P99 块延迟、combine 散射计数偏差；任一项超阈值即回滚到稠密分组 GEMM 路径，牺牲质量对齐换稳定性。</p>\n<h3 id=\"alg-megablocks-dropless-sec-47\">四十七 · 三条路线的问题坐标</h3>\n<p>把无丢弃块稀疏分组 GEMM 放进同族算法谱系里看，它并不是“更好的容量因子路由”，而是对另一组约束的重新取舍。三条路线各自锁定一个失效点：容量因子路由锁定“形状必须静态可预测”，代价是把超出容量的 token 丢掉；专家选择路由锁定“每个专家只处理自己选中的 token”，代价是路由决策依赖后续 token，破坏因果性，自回归解码无法直接用；块稀疏分组 GEMM 锁定“既不丢 token、又要让不规则负载落进高效 MMA”，代价是把对齐责任从 token 级下推到 block 级。选型的第一步不是比吞吐，而是先确认当前负载的失效点落在哪一条上——如果丢弃带来的质量损失可接受且形状抖动是主要矛盾，容量因子路线仍然是最省工程量的；如果任务本身是双向或非因果结构，专家选择路线的质量优势才成立；只有当“不能丢 token”与“必须因果”同时为硬约束时，块稀疏才是唯一可行解。</p>\n<p>三条路线的代价结构完全不同。容量因子路由的代价是质量：丢弃比例随容量因子收紧而上升，且丢弃集中在负载偏斜的专家上，长尾 token 被系统性牺牲。专家选择路由的代价是调度：每个专家独立选 top-k，token 被处理的次数不固定，解码时需要额外的因果掩码或迭代式路由修正。块稀疏的代价是工程复杂度：需要自定义 dispatch/combine kernel，块大小成为硬约束，跨框架移植要重写并重新验证。用公式刻画块稀疏的对齐代价，即块内填充浪费：</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{\\sum_{b}\\left(\\text{block\\_size}-n_b\\right)}{\\sum_{b} n_b}$$</div>\n<p>其中 $n_b$ 为第 b 个非零块的实际 token 数。这个比值直接决定选型：当专家负载分布接近均匀时，$n_b$ 接近 block_size，浪费趋近于零，块稀疏几乎无额外代价；当负载高度偏斜、大量块只含个位数 token 时，浪费上升，块稀疏的相对优势被侵蚀。因此选型表里必须有一列是“专家负载偏斜度”，而不是只看平均吞吐。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-48\">四十八 · 决策表：按约束筛选，而非按跑分排序</h3>\n<p>下表把三条路线放在同一组工程判据下对照。判据顺序即决策顺序：先看硬约束（能否丢 token、是否要求因果），再看负载形态（偏斜度、批大小决定的块数量），最后看工程承受力（自定义 kernel 的维护成本、框架迁移频率）。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>容量因子路由</th><th>专家选择路由</th><th>块稀疏分组 GEMM</th></tr></thead><tbody>\n<tr><td>token 丢弃</td><td>有，随容量因子收紧而增加</td><td>无</td><td>无，块级 padding 替代</td></tr>\n<tr><td>因果性</td><td>保持</td><td>破坏，解码需修正</td><td>保持</td></tr>\n<tr><td>形状可预测性</td><td>高，静态形状</td><td>低，逐专家可变</td><td>中，块数量随批变化</td></tr>\n<tr><td>对齐代价</td><td>丢弃 token 的质量损失</td><td>调度与掩码开销</td><td>块内 padding，通常 &lt;10%</td></tr>\n<tr><td>GEMM 效率</td><td>高（形状规整）</td><td>依赖实现，易碎片化</td><td>接近稠密 GEMM 的 80% 以上</td></tr>\n<tr><td>工程复杂度</td><td>低</td><td>中</td><td>高，需自定义 dispatch/combine</td></tr>\n<tr><td>跨框架移植</td><td>好</td><td>中</td><td>差，换框架需重写验证</td></tr>\n<tr><td>负载偏斜敏感度</td><td>高（丢弃集中）</td><td>中</td><td>高（块内浪费随偏斜上升）</td></tr>\n</tbody></table>\n<p>读表方式：任何一行出现“不可接受”，该路线即出局，不必进入吞吐比较。典型组合是——在线服务、SLO 严格、质量不可退让、框架锁定在 TensorRT-LLM 或 vLLM 单一栈：块稀疏可行但需评估 kernel 维护成本；离线批处理、质量容忍度高、团队 kernel 能力弱：容量因子路由是务实选择；研究型双向模型、非因果结构：专家选择路由。表格不给“最优”，只给排除顺序。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-49\">四十九 · 块大小与批大小的耦合选择</h3>\n<p>块稀疏路线内部还有一个二级决策：block_size 取多少。这不是超参调优，而是与批大小、专家数、负载分布耦合的硬约束。给定批内 token 总数 $T$、专家数 $E$、块容量 $B$，非零块数量的上界约为 $\\min(T, E\\cdot\\lceil T/E\\rceil/B)$ 量级，实际非零块数由路由分布决定。块越小，$n_b$ 越接近 block_size，waste 越低，但 kernel launch 次数与块级 offset/索引生成开销线性上升；块越大，launch 开销摊薄，但小专家所在的块内 padding 显著，waste 上升。材料给出的锚点是 128 token × 1 专家的块粒度，以及 padding 浪费通常低于 10%、分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上——这三个数字构成一个可用的起点，但不是普适最优。</p>\n<p>选择逻辑可以写成一段伪代码式的判据：</p>\n<ul>\n<li>若批内 token 数远大于 $E\\times B$，块数量充足，取较大 $B$ 摊薄 launch 开销，waste 由负载偏斜主导；</li>\n<li>若批内 token 数接近或小于 $E\\times B$，大量块只含少量 token，取较小 $B$ 降低块内浪费，但要核算索引生成开销是否压过收益；</li>\n<li>若专家负载高度偏斜，长尾专家块内 $n_b$ 极小，此时应优先考虑是否改用容量因子路由承担长尾丢弃，而不是继续缩小 $B$；</li>\n<li>若框架迁移频繁，块稀疏的自定义 kernel 需重写验证，应把“移植成本”计入选型，而非只看单栈吞吐。</li>\n</ul>\n<p>系统代价在这里体现为三方拉扯：块小→launch 与索引开销上升（延迟尾部和 CPU 侧开销）；块大→padding 浪费上升（有效 FLOPs 下降，见 $\\text{FLOPs}_{\\text{eff}}$ 中仅非零块计入）；批小→非零块比例低，块稀疏的结构优势被稀释。三者没有同时最优的点，选型即是在给定 SLO 下选一个可接受的折中，并用 waste 与有效 FLOPs 两个指标持续监控。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-50\">五十 · 与量化、并行、分离式部署的叠加条件</h3>\n<p>块稀疏不是孤立算法，它与相邻模块的叠加有明确前提。与 NVFP4/FP8 微缩放量化叠加时，块内 M 维按实际 token 数截断、N/K 维走 tcgen05 的 MMA tile，量化粒度必须与 MMA tile 对齐，否则截断后的块边界会破坏微缩放组的完整性——这是选型时必须验证的兼容点，而不是默认成立。与专家并行 All-to-All 叠加时，块级发送意味着通信粒度从 token 变为块，接收端把同专家块拼接为连续段；若并行拓扑的 All-to-All 实现按 token 粒度优化，块级发送会引入额外的重排开销，需要评估通信侧是否成为新瓶颈。与预填/解码分离部署叠加时，块稀疏主要作用于预填侧的大批 token 分组 GEMM；解码侧批小、块数量少，块稀疏的结构收益下降，此时更应关注解码路径的融合大核与 KV 分页，而不是把块稀疏硬套到解码。</p>\n<p>具体例子：一个预填批含数千 token、专家数为中等规模、路由分布中度偏斜。按 128 token × 1 专家切块，非零块数量足以摊薄 launch 开销，waste 落在 10% 以内，分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上，此时块稀疏是净收益。同一系统切到解码阶段，批内 token 数降到与专家数同量级，非零块大量只含个位数 token，waste 与索引开销同时上升，块稀疏的收益被抵消——这正是“适用边界受 block 大小与专家负载分布约束”的具体含义，也是选型表必须区分预填与解码两段的原因。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-51\">五十一 · 失败模式驱动的回退判据</h3>\n<p>选型不是一次性决定，而是带监控的回退策略。块稀疏路线的三类失败模式各自对应一个回退信号。第一类：块大小失当——block 过小则 kernel launch 与索引开销压过收益，表现为分组 GEMM 之前的准备阶段耗时占比上升；block 过大则小专家块内 padding 显著，表现为 waste 指标越过阈值、有效 FLOPs 下降。第二类：移植性失败——换框架后自定义 dispatch/combine kernel 需重写并重新验证正确性，表现为上线前的正确性回归成本超出预算，此时应回退到容量因子路由以换取工程确定性。第三类：负载偏斜导致的吞吐塌陷——非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，吞吐低于预期，表现为块稀疏吞吐相对稠密 GEMM 的比例跌破 80% 锚点。</p>\n<p>回退判据应当写成可观测的阈值组合，而不是定性描述：waste 越过 10% 锚点、块准备阶段耗时占比上升、分组 GEMM 有效吞吐跌破稠密 GEMM 的 80%、正确性回归成本超出预算——任一条件持续成立，即切换到容量因子路由并接受其丢弃代价，或切换到专家选择路由并承担因果修正开销。反过来，若容量因子路由的丢弃比例在长尾专家上持续偏高、质量指标可测地退化，则应评估迁移到块稀疏，前提是团队具备维护自定义 kernel 的能力。选型的本质是把“质量—工程复杂度—吞吐”三者的交换关系显式化，并用监控指标把交换点钉死，而不是靠一次基准测试定终身。</p>\n<p>最后落在工程判断上：块稀疏分组 GEMM 的价值不在单点吞吐，而在把“不丢 token”从质量诉求变成可调度的结构约束——它用块级 padding 换掉了 token 级丢弃，用自定义 kernel 的维护成本换掉了容量因子路由的质量损失。选它的条件因此可以收敛为一句话：当丢弃不可接受、因果性不可破坏、且团队能承担 dispatch/combine kernel 的长期维护与跨框架重写验证时，块稀疏是三条路线中唯一同时满足硬约束的；否则，容量因子路由的工程确定性或专家选择路由的结构自由度，仍是更合理的起点。</p>\n\n<h3 id=\"alg-megablocks-dropless-sec-52\">五十二 · 块稀疏分组 GEMM 的选型边界：与容量因子、专家选择路由的对照</h3>\n<p>把三种路由对齐方案放在同一条决策轴上，判据不是“谁更先进”，而是“谁在给定负载分布下把浪费与因果性代价压到最低”。容量因子路由用丢弃 token 换取固定形状，其代价直接体现为质量损失，且丢弃比例随专家负载偏斜放大；专家选择路由让专家反向挑 token，破坏自回归因果性，解码阶段无法直接复用。块稀疏分组 GEMM 的取舍点在于：它既不丢 token，也不改因果顺序，代价被转移到块级 padding 与自定义 kernel 上。用浪费公式衡量，$$\\text{waste}=\\frac{\\sum_{b}(\\text{block\\_size}-n_b)}{\\sum_{b} n_b}$$，其中 $n_b$ 为第 $b$ 个非零块的实际 token 数；block_size 取 128 token × 1 专家时，块级 padding 浪费通常低于 10%，而按最大专家负载统一 padding 的方案浪费随偏斜度线性上升。选型的第一个分水岭是：负载偏斜是否稳定。偏斜稳定且专家数少，容量因子路由的丢弃率可控；偏斜剧烈或专家数多，块稀疏的块内截断才划得来。</p>\n<p>第二个分水岭是块大小能否被负载分布“喂饱”。block 过小，非零块数量上升，块级 offset 与块内索引生成、kernel launch 开销压过 padding 收益，尾时延被索引路径拉长；block 过大，小专家块内 padding 显著，浪费公式的分子抬升，吞吐向稠密 GEMM 的 80% 靠拢的优势被吃掉。工程判断是：先统计每个专家的 token 数分布，若多数专家在单批内能填满一个 128 token 块，块稀疏的浪费与索引开销同时处于低位；若大量专家只有零星 token，则应缩小 block 或退回容量因子路由并接受可控丢弃。这一步没有通用最优块大小，只有与批大小、专家数、负载偏斜三者匹配的块大小。</p>\n<p>第三个分水岭是框架移植成本。块稀疏方案要求自定义 dispatch/combine kernel，跨框架移植性差，换框架后需重写并重新验证正确性；容量因子路由与专家选择路由在主流框架中已有现成实现，迁移成本低。因此决策表应按“质量约束强度 × 负载偏斜度 × 框架锁定程度”三列展开：质量不可妥协且偏斜剧烈，选块稀疏；质量可容忍少量丢弃且偏斜温和，选容量因子；解码因果性不可破坏且不愿写自定义 kernel，则只能在容量因子与专家选择之间做取舍，块稀疏是唯一同时满足无丢弃与因果性的选项，代价是工程复杂度。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>token 丢弃</th><th>因果性</th><th>主要系统代价</th><th>适用条件</th></tr></thead><tbody><tr><td>容量因子路由</td><td>有</td><td>保持</td><td>质量损失随偏斜放大</td><td>偏斜温和、框架锁定</td></tr><tr><td>专家选择路由</td><td>无</td><td>破坏</td><td>解码不可复用</td><td>仅预填或非因果场景</td></tr><tr><td>块稀疏分组 GEMM</td><td>无</td><td>保持</td><td>索引开销、自定义 kernel</td><td>偏斜剧烈、质量优先</td></tr></tbody></table>\n<p>失效条件集中在两处：专家负载高度偏斜时，非零块数量与块内截断频繁变化，块级 offset 与索引生成开销上升，吞吐低于预期，此时块稀疏的收益被索引路径吞掉；块大小选择失当则直接触发浪费或 launch 开销的恶性循环。系统代价的量化锚点是分组 GEMM 吞吐接近稠密 GEMM 的 80% 以上，这意味着块稀疏不是免费的质量保险，它用约两成的吞吐折损换无丢弃；当 SLO 对尾时延敏感而批大小不足以让块填满时，这笔折损会体现在 P99 上而非均值上。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 分组GEMM与tcgen05</td></tr><tr><td>解决什么</td><td>容量因子路由靠丢弃保形状，专家选择路由破坏因果性；需要一种既不丢 token 又能把不规则专家负载映射到高效 GEMM…</td></tr><tr><td>一句话机制</td><td>用块稀疏（block-sparse）矩阵乘替代固定容量的分组 GEMM：把 token×专家 的稀疏路由矩阵按固定 b…</td></tr><tr><td>代价与失效</td><td>块大小是硬约束：block 越小浪费越少但 kernel launch 与索引开销越大，block 越大则小专家浪费显著；实现复杂度高，需…</td></tr><tr><td>后继</td><td>MoE KV cache 分层压缩</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-megablocks-dropless · 共 8 个片段</p>\n";break;}}})();
